    );
    bytes32 public constant SHARED_COMPONENT_IDENTITY_TYPEHASH = keccak256(
        "ProgrammableCompletedGraphSharedComponentIdentityV1(address account,uint8 kind,uint8 deploymentKind,address deployer,uint64 createNonce,bytes32 create2Salt,bytes32 initCodeHash,bytes32 creationReceiptEvidenceHash,bytes32 externalCanonicalIdHash,bytes32 runtimeCodeHash,bytes32 intrinsicConfigurationHash)"
    );
    bytes32 public constant COMPONENT_CREATION_EVIDENCE_TYPEHASH = keccak256(
        "ProgrammableCompletedGraphAdoptionCreationEvidenceV1(bytes32 sourceBindingHash,bytes32 componentBindingHash)"
    );
    bytes32 public constant COMPONENT_CREATION_EVIDENCE_SOURCE_TYPEHASH = keccak256(
        "ProgrammableCompletedGraphAdoptionCreationEvidenceSourceV1(uint256 chainId,address registry,bytes32 sourceRepositoryHash,bytes32 sourceCommitHash,bytes32 sourceTreeHash,bytes32 sourceLaunchId,bytes32 manifestHash,bytes32 policyHash,bytes32 applicantPlanArtifactHash,address launchWallet)"
    );
    bytes32 public constant COMPONENT_CREATION_EVIDENCE_COMPONENT_TYPEHASH = keccak256(
        "ProgrammableCompletedGraphAdoptionCreationEvidenceComponentV1(uint256 componentIndex,address account,uint8 kind,uint8 scope,uint8 deploymentKind,address deployer,uint64 createNonce,bytes32 create2Salt,bytes32 initCodeHash,bytes32 creationReceiptEvidenceHash,bytes32 externalCanonicalIdHash,bytes32 runtimeCodeHash)"
    );
    bytes32 public constant CREATION_RECEIPT_EVIDENCE_TYPEHASH = keccak256(
        "ProgrammableCompletedGraphCreationReceiptEvidenceV1(bytes32 transactionHash,uint64 blockNumber,bytes32 blockHash,uint32 transactionIndex,address transactionSender,uint64 transactionSenderNonce,address transactionTo,uint256 transactionValueWei,bytes32 transactionInputHash,bool receiptSucceeded,address topLevelCreatedAddress,bytes32 internalCreationTraceHash,bytes32 finalityEvidenceHash,bytes32 dualProviderEvidenceHash)"
    );
    bytes32 public constant EDGE_TYPEHASH = keccak256(
        "ProgrammableCompletedGraphAdoptionEdgeV1(uint8 fromIndex,uint8 toIndex,uint8 kind,bytes32 relationHash)"
    );
    bytes32 public constant COMPONENT_GRAPH_TYPEHASH =
        keccak256("ProgrammableCompletedGraphAdoptionGraphV1(bytes32 componentsHash,bytes32 edgesHash)");
    bytes32 public constant RUNTIME_SET_TYPEHASH =
        keccak256("ProgrammableCompletedGraphAdoptionRuntimeSetV1(bytes32 orderedCommitmentsHash)");
    bytes32 public constant CONFIGURATION_SET_TYPEHASH =
        keccak256("ProgrammableCompletedGraphAdoptionConfigurationSetV1(bytes32 orderedCommitmentsHash)");
    bytes32 public constant CONFIGURATION_TYPEHASH = keccak256(
        "ProgrammableCompletedGraphAdoptionConfigurationV1(bytes32 componentGraphHash,bytes32 componentConfigurationSetHash,bytes32 policyHash,bytes32 revenueBindingHash,address poolManager,bytes32 poolManagerRuntimeCodeHash,bytes32 poolKeyHash,bytes32 architectureResultHash)"
    );
    bytes32 public constant RESULT_TYPEHASH = keccak256(
        "ProgrammableCompletedGraphAdoptionResultV1(bytes32 componentGraphHash,bytes32 configurationHash,bytes32 architectureResultHash,bytes32 poolResultHash,bytes32 deploymentLineageHash)"
    );
    bytes32 public constant APPLICATION_IDENTITY_TYPEHASH = keccak256(
        "ProgrammableCompletedGraphApplicationIdentityV1(address account,bytes32 runtimeCodeHash,bytes32 configurationHash)"
    );
    bytes32 public constant CANONICAL_RECEIPT_CORE_TYPEHASH = keccak256(
        "ProgrammableCompletedGraphCanonicalReceiptCoreV1(bytes32 stampLaunchId,bytes32 sourceLaunchId,bytes32 launchGrantDigest,bytes32 launchGrantHash,bytes32 executionCurrentnessDigest,bytes32 contractPlanHash,bytes32 profileCapabilityHash,bytes32 adoptionRequestHash)"
    );
    bytes32 public constant FINALITY_INDEXING_RECEIPT_TYPEHASH =
        keccak256("ProgrammableCompletedGraphFinalityIndexingReceiptV1(bytes32 abiEncodedReceiptWithoutHash)");

    /// @dev Static tuple used only to avoid compiler stack pressure. ABI encoding is the exact flat winner preimage.
    struct WinnerKeyDomainV1 {
        uint256 chainId;
        address registry;
        address launchWallet;
        bytes32 applicantIdHash;
        bytes32 profileKey;
        bytes32 profileDescriptorHash;
        bytes32 exactContractBindingHash;
        bytes32 sourceRepositoryHash;
        bytes32 sourceCommitHash;
        bytes32 sourceTreeHash;
        bytes32 sourceLaunchId;
        bytes32 contractPlanHash;
        bytes32 applicantPlanArtifactHash;
        bytes32 componentGraphHash;
        bytes32 adoptionIntentHash;
        uint64 securityEpoch;
        bytes32 securityEpochHash;
        uint64 policyEpoch;
        bytes32 policyEpochHash;
        uint64 reviewGeneration;
        bytes32 reviewGenerationHash;
    }

    struct LaunchGrantReviewDomainV1 {
        bytes32 builderEvidenceHash;
        bytes32 reviewerAttestationHash;
        bytes32 securityControlHeadHash;
        bytes32 securityEpochHash;
        bytes32 policyHash;
        bytes32 policyEpochHash;
        bytes32 reviewGenerationHash;
        uint64 securityEpoch;
        uint64 policyEpoch;
        uint64 reviewGeneration;
        bytes32 antiReplayNonce;
        bytes32 winnerKeyHash;
    }

    error InvalidGitObjectId();

    function computeSourceCommitHash(bytes20 gitObjectId) external pure returns (bytes32) {
        return _sourceCommitHash(gitObjectId);
    }

    function computeSourceTreeHash(bytes20 gitObjectId) external pure returns (bytes32) {
        return _sourceTreeHash(gitObjectId);
    }

    function sourceRevisionMatches(
        bytes20 sourceCommitId,
        bytes20 sourceTreeId,
        bytes32 sourceCommitHash,
        bytes32 sourceTreeHash
    ) external pure returns (bool) {
        return sourceCommitId != bytes20(0) && sourceTreeId != bytes20(0)
            && sourceCommitHash == _sourceCommitHash(sourceCommitId) && sourceTreeHash == _sourceTreeHash(sourceTreeId);
    }

    function computeProfileKey(bytes32 profileDescriptorHash, bytes32 routeSchemaHash) external pure returns (bytes32) {
        return keccak256(abi.encode(PROFILE_KEY_TYPEHASH, profileDescriptorHash, routeSchemaHash));
    }

    function computePlanHash(IProgrammableCompletedGraphAdoptionCompatV1.CompletedGraphPlanV1 calldata plan)
        external
        pure
        returns (bytes32)
    {
        return keccak256(abi.encode(PLAN_TYPEHASH, keccak256(abi.encode(plan))));
    }

    function computeLaunchGrantStructHash(IProgrammableCompletedGraphAdoptionCompatV1.LaunchGrantV1 calldata grant)
        external
        pure
        returns (bytes32)
    {
        return _launchGrantHash(grant);
    }

    function computeLaunchGrantHash(IProgrammableCompletedGraphAdoptionCompatV1.LaunchGrantV1 calldata grant)
        external
        pure
        returns (bytes32)
    {
        return _launchGrantHash(grant);
    }

    function computeAdoptionPreflightQueryHash(
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightQueryV1 calldata query
    ) external pure returns (bytes32) {
        return keccak256(abi.encode(PREFLIGHT_QUERY_TYPEHASH, keccak256(abi.encode(query))));
    }

    function computeAdoptionPreflightReadbackHash(bytes32 globalReadbackHeadHash, bytes32 orderedComponentLeavesHash)
        external
        pure
        returns (bytes32)
    {
        return keccak256(abi.encode(PREFLIGHT_READBACK_TYPEHASH, globalReadbackHeadHash, orderedComponentLeavesHash));
    }

    function computeAdoptionPreflightComponentLeafHash(
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightQueryV1 calldata query,
        bytes32 actualRuntimeCodeHash,
        bytes32 exclusiveComponentOccupantStampLaunchId,
        bytes32 sharedComponentIdentityHash
    ) external pure returns (bytes32) {
        return keccak256(
            abi.encode(
                PREFLIGHT_COMPONENT_LEAF_TYPEHASH,
                query.componentIndex,
                query.component,
                query.componentScope,
                query.expectedSharedIdentityHash,
                query.expectedRuntimeCodeHash,
                actualRuntimeCodeHash,
                exclusiveComponentOccupantStampLaunchId,
                sharedComponentIdentityHash
            )
        );
    }

    function computeAdoptionPreflightGlobalHeadHash(
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightReadbackV1 calldata readback
    ) external pure returns (bytes32) {
        bytes32 runtimeControlHash = keccak256(
            abi.encode(
                PREFLIGHT_RUNTIME_CONTROL_TYPEHASH,
                readback.chainId,
                readback.registry,
                readback.runtimeAuthorityBindingHash,
                readback.liveRuntimeMask,
                readback.dependencyBehaviorEvidenceHash,
                readback.securityControlHeadHash,
                readback.securityEpoch,
                readback.securityEpochHash,
                readback.policyEpoch,
                readback.policyEpochHash,
                readback.reviewControl.reviewGenerationHash,
                readback.reviewControl.reviewGeneration,
                readback.globalAdoptionKilled
            )
        );
        bytes32 lifecycleHash = keccak256(
            abi.encode(
                PREFLIGHT_LIFECYCLE_TYPEHASH,
                readback.profileStatus,
                readback.profileCapabilityHash,
                readback.grantStateHead.stateHeadHash,
                readback.winnerNonceOccupantGrantDigest,
                readback.winnerKeyOccupantGrantDigest,
                readback.currentnessNonceUsed,
                readback.receiptStatus,
                readback.receiptCoreHash,
                readback.finalityIndexingReceiptHash
            )
        );
        bytes32 reservationHash = keccak256(
            abi.encode(
                PREFLIGHT_RESERVATION_TYPEHASH,
                readback.graphOccupantStampLaunchId,
                readback.exclusiveTokenOccupantStampLaunchId,
                readback.poolOccupantStampLaunchId
            )
        );
        return keccak256(
            abi.encode(
                PREFLIGHT_GLOBAL_HEAD_TYPEHASH, readback.queryHash, runtimeControlHash, lifecycleHash, reservationHash
            )
        );
    }

    function computeExecutionCurrentnessStructHash(
        IProgrammableCompletedGraphAdoptionCompatV1.ExecutionCurrentnessV1 calldata currentness
    ) external pure returns (bytes32) {
        return keccak256(abi.encode(EXECUTION_CURRENTNESS_TYPEHASH, keccak256(abi.encode(currentness))));
    }

    function computeAdoptionRequestHash(IProgrammableCompletedGraphAdoptionCompatV1.AdoptionRequestV1 calldata request)
        external
        pure
        returns (bytes32)
    {
        return keccak256(abi.encode(ADOPTION_REQUEST_TYPEHASH, keccak256(abi.encode(request))));
    }

    function computeAdoptionProfileCapabilityHash(
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionProfileCapabilityV1 calldata capability
    ) external pure returns (bytes32) {
        return keccak256(abi.encode(PROFILE_CAPABILITY_TYPEHASH, keccak256(abi.encode(capability))));
    }

    function computeStampLaunchId(
        address registry,
        address launchWallet,
        bytes32 profileKey,
        bytes32 contractPlanHash,
        bytes32 sourceLaunchId
    ) external view returns (bytes32) {
        return keccak256(
            abi.encode(
                STAMP_LAUNCH_ID_TYPEHASH,
                block.chainid,
                registry,
                launchWallet,
                profileKey,
                contractPlanHash,
                sourceLaunchId
            )
        );
    }

    /// @notice Canonical one-winner domain. The supplied `winnerKeyHash` is deliberately excluded from its preimage.
    function computeWinnerKeyHash(IProgrammableCompletedGraphAdoptionCompatV1.LaunchGrantV1 calldata grant)
        external
        pure
        returns (bytes32)
    {
        return _winnerKeyHash(grant);
    }

    function computeComponentConfigurationHash(
        IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1 calldata component
    ) external pure returns (bytes32) {
        return _componentConfigurationHash(component);
    }

    /// @notice Plan-independent canonical identity for a shared component account.
    /// @dev Deliberately excludes source/plan-bound creation evidence and the derived configuration hash.
    function computeSharedComponentIdentityHash(
        IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1 calldata component
    ) external pure returns (bytes32) {
        return _sharedComponentIdentityHash(component);
    }

    function computeCreationReceiptEvidenceHash(
        IProgrammableCompletedGraphAdoptionCompatV1.CreationReceiptEvidenceV1 calldata evidence
    ) external pure returns (bytes32) {
        return _creationReceiptEvidenceHash(evidence);
    }

    function computeComponentCreationEvidenceHash(
        address registry,
        IProgrammableCompletedGraphAdoptionCompatV1.CompletedGraphPlanV1 calldata plan,
        uint256 componentIndex,
        IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1 calldata component
    ) external view returns (bytes32) {
        bytes32 sourceBindingHash = keccak256(
            abi.encode(
                COMPONENT_CREATION_EVIDENCE_SOURCE_TYPEHASH,
                block.chainid,
                registry,
                plan.sourceRepositoryHash,
                _sourceCommitHash(plan.sourceCommitId),
                _sourceTreeHash(plan.sourceTreeId),
                plan.sourceLaunchId,
                plan.manifestHash,
                plan.policyHash,
                plan.applicantPlanArtifactHash,
                plan.launchWallet
            )
        );
        bytes32 componentBindingHash = keccak256(
            abi.encode(
                COMPONENT_CREATION_EVIDENCE_COMPONENT_TYPEHASH,
                componentIndex,
                component.account,
                uint8(component.kind),
                uint8(component.scope),
                uint8(component.deploymentKind),
                component.deployer,
                component.createNonce,
                component.create2Salt,
                component.initCodeHash,
                _creationReceiptEvidenceHash(component.creationReceiptEvidence),
                component.externalCanonicalIdHash,
                component.runtimeCodeHash
            )
        );
        return keccak256(abi.encode(COMPONENT_CREATION_EVIDENCE_TYPEHASH, sourceBindingHash, componentBindingHash));
    }

    function computeComponentGraphHash(
        IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1[] calldata components,
        IProgrammableCompletedGraphAdoptionCompatV1.GraphEdgeV1[] calldata edges
    ) external pure returns (bytes32) {
        bytes32[] memory componentHashes = new bytes32[](components.length);
        for (uint256 i; i < components.length; ++i) {
            componentHashes[i] = _componentHash(components[i]);
        }
        bytes32[] memory edgeHashes = new bytes32[](edges.length);
        for (uint256 i; i < edges.length; ++i) {
            IProgrammableCompletedGraphAdoptionCompatV1.GraphEdgeV1 calldata edge = edges[i];
            edgeHashes[i] =
                keccak256(abi.encode(EDGE_TYPEHASH, edge.fromIndex, edge.toIndex, uint8(edge.kind), edge.relationHash));
        }
        return keccak256(
            abi.encode(
                COMPONENT_GRAPH_TYPEHASH,
                keccak256(abi.encodePacked(componentHashes)),
                keccak256(abi.encodePacked(edgeHashes))
            )
        );
    }

    function computeExactRuntimeSetHash(IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1[] calldata components)
        external
        pure
        returns (bytes32 result)
    {
        result = keccak256(abi.encode(RUNTIME_SET_TYPEHASH));
        for (uint256 i; i < components.length; ++i) {
            IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1 calldata component = components[i];
            result = keccak256(abi.encode(result, component.account, component.runtimeCodeHash));
        }
    }

    function computeComponentConfigurationSetHash(IProgrammableCompletedGraphAdoptionCompatV1
                .ComponentV1[] calldata components) external pure returns (bytes32 result) {
        result = keccak256(abi.encode(CONFIGURATION_SET_TYPEHASH));
        for (uint256 i; i < components.length; ++i) {
            result = keccak256(abi.encode(result, components[i].configurationHash));
        }
    }

    function computeConfigurationHash(
        bytes32 componentGraphHash,
        bytes32 componentConfigurationSetHash,
        bytes32 policyHash,
        bytes32 revenueBindingHash,
        address poolManager,
        bytes32 poolManagerRuntimeCodeHash,
        bytes32 poolKeyHash,
        bytes32 architectureResultHash
    ) external pure returns (bytes32) {
        return keccak256(
            abi.encode(
                CONFIGURATION_TYPEHASH,
                componentGraphHash,
                componentConfigurationSetHash,
                policyHash,
                revenueBindingHash,
                poolManager,
                poolManagerRuntimeCodeHash,
                poolKeyHash,
                architectureResultHash
            )
        );
    }

    function computeResultHash(
        bytes32 componentGraphHash,
        bytes32 configurationHash,
        bytes32 architectureResultHash,
        bytes32 poolResultHash,
        bytes32 deploymentLineageHash
    ) external pure returns (bytes32) {
        return keccak256(
            abi.encode(
                RESULT_TYPEHASH,
                componentGraphHash,
                configurationHash,
                architectureResultHash,
                poolResultHash,
                deploymentLineageHash
            )
        );
    }

    function computeApplicationIdentityHash(IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1 calldata component)
        external
        pure
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                APPLICATION_IDENTITY_TYPEHASH, component.account, component.runtimeCodeHash, component.configurationHash
            )
        );
    }

    /// @notice Hashes the compact canonical receipt after forcing its self-hash field to zero.
    function computeCanonicalReceiptCoreHash(
        IProgrammableCompletedGraphAdoptionCompatV1.CanonicalReceiptCoreV1 calldata core
    ) external pure returns (bytes32) {
        return keccak256(
            abi.encode(
                CANONICAL_RECEIPT_CORE_TYPEHASH,
                core.stampLaunchId,
                core.sourceLaunchId,
                core.launchGrantDigest,
                core.launchGrantHash,
                core.executionCurrentnessDigest,
                core.contractPlanHash,
                core.profileCapabilityHash,
                core.adoptionRequestHash
            )
        );
    }

    /// @notice Hashes a finality/indexing append after forcing its self-hash field to zero.
    function computeFinalityIndexingReceiptHash(
        IProgrammableCompletedGraphAdoptionCompatV1.FinalityIndexingReceiptV1 calldata receipt
    ) external pure returns (bytes32) {
        IProgrammableCompletedGraphAdoptionCompatV1.FinalityIndexingReceiptV1 memory normalized = receipt;
        normalized.finalityIndexingReceiptHash = bytes32(0);
        return keccak256(abi.encode(FINALITY_INDEXING_RECEIPT_TYPEHASH, keccak256(abi.encode(normalized))));
    }

    function _componentConfigurationHash(IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1 calldata component)
        private
        pure
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                COMPONENT_CONFIGURATION_TYPEHASH,
                component.account,
                uint8(component.kind),
                uint8(component.scope),
                uint8(component.deploymentKind),
                component.deployer,
                component.createNonce,
                component.create2Salt,
                component.initCodeHash,
                _creationReceiptEvidenceHash(component.creationReceiptEvidence),
                component.externalCanonicalIdHash,
                component.runtimeCodeHash
            )
        );
    }

    function _componentHash(IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1 calldata component)
        private
        pure
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                COMPONENT_TYPEHASH,
                component.account,
                uint8(component.kind),
                uint8(component.scope),
                uint8(component.deploymentKind),
                component.deployer,
                component.createNonce,
                component.create2Salt,
                component.initCodeHash,
                _creationReceiptEvidenceHash(component.creationReceiptEvidence),
                component.externalCanonicalIdHash,
                component.runtimeCodeHash,
                component.configurationHash,
                component.creationEvidenceHash
            )
        );
    }

    function _sharedComponentIdentityHash(IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1 calldata component)
        private
        pure
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                SHARED_COMPONENT_IDENTITY_TYPEHASH,
                component.account,
                uint8(component.kind),
                uint8(component.deploymentKind),
                component.deployer,
                component.createNonce,
                component.create2Salt,
                component.initCodeHash,
                _creationReceiptEvidenceHash(component.creationReceiptEvidence),
                component.externalCanonicalIdHash,
                component.runtimeCodeHash,
                component.configurationHash
            )
        );
    }

    function _launchGrantHash(IProgrammableCompletedGraphAdoptionCompatV1.LaunchGrantV1 calldata grant)
        private
        pure
        returns (bytes32)
    {
        bytes32 bindingAHash = keccak256(
            abi.encode(
                LAUNCH_GRANT_BINDING_A_TYPEHASH,
                grant.chainId,
                grant.registry,
                grant.launchWallet,
                grant.applicantIdHash,
                grant.profileKey,
                grant.profileDescriptorHash,
                grant.exactContractBindingHash,
                grant.contractPlanHash,
                grant.applicantPlanArtifactHash,
                grant.adoptionIntentHash,
                uint8(grant.executionReadiness),
                grant.executionReadinessConstraintHash
            )
        );
        bytes32 bindingBHash = keccak256(
            abi.encode(
                LAUNCH_GRANT_BINDING_B_TYPEHASH,
                uint8(grant.executionTimeConstraint),
                grant.executionTimeConstraintEvidenceHash,
                grant.sourceRepositoryHash,
                grant.sourceCommitHash,
                grant.sourceTreeHash,
                grant.sourceLaunchId,
                grant.componentGraphHash,
                grant.exactRuntimeSetHash,
                grant.componentConfigurationSetHash,
                grant.revenueBindingHash,
                grant.resultHash
            )
        );
        LaunchGrantReviewDomainV1 memory review;
        review.builderEvidenceHash = grant.builderEvidenceHash;
        review.reviewerAttestationHash = grant.reviewerAttestationHash;
        review.securityControlHeadHash = grant.securityControlHeadHash;
        review.securityEpochHash = grant.securityEpochHash;
        review.policyHash = grant.policyHash;
        review.policyEpochHash = grant.policyEpochHash;
        review.reviewGenerationHash = grant.reviewControl.reviewGenerationHash;
        review.securityEpoch = grant.securityEpoch;
        review.policyEpoch = grant.policyEpoch;
        review.reviewGeneration = grant.reviewControl.reviewGeneration;
        review.antiReplayNonce = grant.antiReplayNonce;
        review.winnerKeyHash = grant.winnerKeyHash;
        bytes32 reviewHash = keccak256(abi.encode(LAUNCH_GRANT_REVIEW_TYPEHASH, review));
        return keccak256(abi.encode(LAUNCH_GRANT_TYPEHASH, bindingAHash, bindingBHash, reviewHash));
    }

    function _winnerKeyHash(IProgrammableCompletedGraphAdoptionCompatV1.LaunchGrantV1 calldata grant)
        private
        pure
        returns (bytes32)
    {
        WinnerKeyDomainV1 memory domain;
        domain.chainId = grant.chainId;
        domain.registry = grant.registry;
        domain.launchWallet = grant.launchWallet;
        domain.applicantIdHash = grant.applicantIdHash;
        domain.profileKey = grant.profileKey;
        domain.profileDescriptorHash = grant.profileDescriptorHash;
        domain.exactContractBindingHash = grant.exactContractBindingHash;
        domain.sourceRepositoryHash = grant.sourceRepositoryHash;
        domain.sourceCommitHash = grant.sourceCommitHash;
        domain.sourceTreeHash = grant.sourceTreeHash;
        domain.sourceLaunchId = grant.sourceLaunchId;
        domain.contractPlanHash = grant.contractPlanHash;
        domain.applicantPlanArtifactHash = grant.applicantPlanArtifactHash;
        domain.componentGraphHash = grant.componentGraphHash;
        domain.adoptionIntentHash = grant.adoptionIntentHash;
        domain.securityEpoch = grant.securityEpoch;
        domain.securityEpochHash = grant.securityEpochHash;
        domain.policyEpoch = grant.policyEpoch;
        domain.policyEpochHash = grant.policyEpochHash;
        domain.reviewGeneration = grant.reviewControl.reviewGeneration;
        domain.reviewGenerationHash = grant.reviewControl.reviewGenerationHash;
        return keccak256(abi.encode(WINNER_KEY_TYPEHASH, domain));
    }

    function _creationReceiptEvidenceHash(
        IProgrammableCompletedGraphAdoptionCompatV1.CreationReceiptEvidenceV1 calldata evidence
    ) private pure returns (bytes32) {
        return keccak256(abi.encode(CREATION_RECEIPT_EVIDENCE_TYPEHASH, evidence));
    }

    function _sourceCommitHash(bytes20 gitObjectId) private pure returns (bytes32) {
        if (gitObjectId == bytes20(0)) revert InvalidGitObjectId();
        return keccak256(abi.encode(SOURCE_COMMIT_TYPEHASH, gitObjectId));
    }

    function _sourceTreeHash(bytes20 gitObjectId) private pure returns (bytes32) {
        if (gitObjectId == bytes20(0)) revert InvalidGitObjectId();
        return keccak256(abi.encode(SOURCE_TREE_TYPEHASH, gitObjectId));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { IProgrammableCompletedGraphAdoptionCompatV1 } from "./IProgrammableCompletedGraphAdoptionCompatV1.sol";
import { ProgrammableCompletedGraphAdoptionCompatCodecV1 } from "./ProgrammableCompletedGraphAdoptionCompatCodecV1.sol";
import { ProgrammableCompletedGraphAdoptionPreflightV1 } from "./ProgrammableCompletedGraphAdoptionPreflightV1.sol";
import { ProgrammableCompletedGraphAdoptionValidatorV1 } from "./ProgrammableCompletedGraphAdoptionValidatorV1.sol";

/// @dev Minimal local ERC-1271 surface. The implementation is codehash-pinned by the Registry.
interface IERC1271CompatV1 {
    function isValidSignature(bytes32 hash, bytes calldata signature) external view returns (bytes4 magicValue);
}

/// @notice Canonical evergreen LaunchGrant, source-neutral completed-graph adoption and receipt registry.
/// @dev This contract does not deploy, initialize, call, delegatecall, transfer, approve, or fund any component. It
///      proves only a completed graph's typed provenance/current code commitments, then atomically marks a reviewed
///      grant Consumed and anchors the canonical adoption receipt.
contract ProgrammableCompletedGraphAdoptionGrantRegistryV1 is IProgrammableCompletedGraphAdoptionCompatV1 {
    uint64 private constant MAX_CURRENTNESS_LIFETIME = 1 hours;
    uint256 private constant MAX_SIGNATURE_BYTES = 4096;
    uint256 private constant AUTHORITY_GAS_RESERVE = 2_000_000;
    uint256 private constant MAX_AUTHORITY_STATICCALL_GAS = 500_000;

    uint16 private constant IDENTITY_POOL = 1 << 4;

    bytes32 private constant GRANT_STATE_HEAD_TYPEHASH = keccak256(
        "ProgrammableCompletedGraphGrantStateHeadV1(bytes32 grantDigest,bytes32 grantHash,bytes32 stampLaunchId,uint8 status)"
    );
    bytes32 private constant PREFLIGHT_AUTHORITY_ROLES_TYPEHASH = keccak256(
        "ProgrammableCompletedGraphAdoptionPreflightAuthorityRolesV1(address reviewerAuthority,bytes32 reviewerAuthorityRuntimeCodeHash,address governance,bytes32 governanceRuntimeCodeHash,address finalityAuthority,bytes32 finalityAuthorityRuntimeCodeHash,address indexerAuthority,bytes32 indexerAuthorityRuntimeCodeHash)"
    );
    bytes32 private constant PREFLIGHT_CORE_DEPENDENCIES_TYPEHASH = keccak256(
        "ProgrammableCompletedGraphAdoptionPreflightCoreDependenciesV1(address codec,bytes32 codecRuntimeCodeHash,address validator,bytes32 validatorRuntimeCodeHash,address preflight,bytes32 preflightRuntimeCodeHash)"
    );
    bytes32 private constant PREFLIGHT_BASE_RUNTIME_BINDING_TYPEHASH = keccak256(
        "ProgrammableCompletedGraphAdoptionPreflightBaseRuntimeBindingV1(uint256 chainId,address registry,bytes32 authorityRolesHash,bytes32 coreDependenciesHash,bytes32 dependencyBehaviorEvidenceHash)"
    );
    bytes32 private constant PREFLIGHT_PROFILE_RUNTIME_BINDING_TYPEHASH = keccak256(
        "ProgrammableCompletedGraphAdoptionPreflightProfileRuntimeBindingV1(address stateVerifier,bytes32 stateVerifierRuntimeCodeHash,uint256 canonicalPoolManagerChainId,address canonicalPoolManager,bytes32 canonicalPoolManagerRuntimeCodeHash)"
    );
    bytes32 private constant PREFLIGHT_RUNTIME_AUTHORITY_BINDING_TYPEHASH = keccak256(
        "ProgrammableCompletedGraphAdoptionPreflightRuntimeAuthorityBindingV1(bytes32 baseRuntimeBindingHash,bytes32 profileRuntimeBindingHash)"
    );

    uint16 private constant RUNTIME_REVIEWER = 1 << 0;
    uint16 private constant RUNTIME_GOVERNANCE = 1 << 1;
    uint16 private constant RUNTIME_FINALITY = 1 << 2;
    uint16 private constant RUNTIME_INDEXER = 1 << 3;
    uint16 private constant RUNTIME_CODEC = 1 << 4;
    uint16 private constant RUNTIME_VALIDATOR = 1 << 5;
    uint16 private constant RUNTIME_STATE_VERIFIER = 1 << 6;
    uint16 private constant RUNTIME_POOL_MANAGER = 1 << 7;
    uint16 private constant RUNTIME_PREFLIGHT = 1 << 8;

    bytes32 private constant EIP712_DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");
    bytes32 private constant EIP712_NAME_HASH = keccak256("ProgrammableCompletedGraphAdoptionGrantRegistry");
    bytes32 private constant EIP712_VERSION_HASH = keccak256("1");
    bytes4 private constant ERC1271_MAGICVALUE = 0x1626ba7e;

    struct InitialControlStateV1 {
        bytes32 dependencyBehaviorEvidenceHash;
        bytes32 securityControlHeadHash;
        uint64 securityEpoch;
        bytes32 securityEpochHash;
        uint64 policyEpoch;
        bytes32 policyEpochHash;
        uint64 reviewGeneration;
        bytes32 reviewGenerationHash;
    }

    address private immutable REVIEWER_AUTHORITY;
    bytes32 private immutable REVIEWER_AUTHORITY_RUNTIME_CODE_HASH;
    address private immutable GOVERNANCE;
    bytes32 private immutable GOVERNANCE_RUNTIME_CODE_HASH;
    address private immutable FINALITY_AUTHORITY;
    bytes32 private immutable FINALITY_AUTHORITY_RUNTIME_CODE_HASH;
    address private immutable INDEXER_AUTHORITY;
    bytes32 private immutable INDEXER_AUTHORITY_RUNTIME_CODE_HASH;
    ProgrammableCompletedGraphAdoptionCompatCodecV1 private immutable CODEC;
    bytes32 private immutable CODEC_RUNTIME_CODE_HASH;
    ProgrammableCompletedGraphAdoptionValidatorV1 private immutable VALIDATOR;
    bytes32 private immutable VALIDATOR_RUNTIME_CODE_HASH;
    ProgrammableCompletedGraphAdoptionPreflightV1 private immutable PREFLIGHT;
    bytes32 private immutable PREFLIGHT_RUNTIME_CODE_HASH;
    /// @notice Frozen review commitment for forwarding/mutable behavior behind the fixed constructor dependencies.
    /// @dev Rejecting bytecode that contains DELEGATECALL does not prove that other forwarding paths are immutable.
    bytes32 private immutable DEPENDENCY_BEHAVIOR_EVIDENCE_HASH;
    bytes32 private immutable BASE_RUNTIME_AUTHORITY_BINDING_HASH;

    uint64 private _securityEpoch;
    bytes32 private _securityControlHeadHash;
    bytes32 private _securityEpochHash;
    uint64 private _policyEpoch;
    bytes32 private _policyEpochHash;
    uint64 private _reviewGeneration;
    bytes32 private _reviewGenerationHash;
    uint256 private _reentrancyState = 1;

    mapping(bytes32 profileKey => AdoptionProfileCapabilityV1 capability) private _profileCapability;
    mapping(bytes32 profileKey => bytes32 capabilityHash) private _profileCapabilityHash;
    mapping(bytes32 profileKey => bytes32 runtimeBindingHash) private _profileRuntimeBindingHash;
    mapping(bytes32 profileKey => ProfileStatusV1 status) private _profileStatus;
    mapping(bytes32 grantDigest => bytes32 grantHash) private _grantHash;
    mapping(bytes32 grantDigest => bytes32 stampLaunchId) private _stampLaunchIdByGrantDigest;
    mapping(bytes32 grantDigest => GrantStatusV1 status) private _grantStatus;
    mapping(bytes32 stampLaunchId => ReceiptStatusV1 status) private _receiptStatus;
    mapping(bytes32 stampLaunchId => CanonicalReceiptCoreV1 core) private _canonicalReceiptCore;
    mapping(bytes32 stampLaunchId => bytes32 receiptHash) private _finalityIndexingReceiptHash;
    mapping(bytes32 nonce => bytes32 grantDigest) private _grantDigestByWinnerNonce;
    mapping(bytes32 winnerKeyHash => bytes32 grantDigest) private _grantDigestByWinnerKeyHash;
    mapping(bytes32 componentGraphHash => bytes32 stampLaunchId) private _stampLaunchIdByGraphHash;
    mapping(address component => bytes32 stampLaunchId) private _exclusiveComponentStampLaunchId;
    mapping(address component => bytes32 identityHash) private _sharedComponentIdentityHash;
    mapping(address token => bytes32 stampLaunchId) private _stampLaunchIdByExclusiveToken;
    mapping(bytes32 poolLookup => bytes32 stampLaunchId) private _stampLaunchIdByPool;
    mapping(bytes32 currentnessDigest => bool used) private _usedCurrentnessDigest;
    mapping(bytes32 currentnessDigest => bool revoked) private _revokedCurrentnessDigest;
    mapping(bytes32 currentnessNonce => bool used) private _usedCurrentnessNonce;
    bool private _globalAdoptionKilled;
    uint64 private _killSecurityEpoch;
    uint64 private _killPolicyEpoch;
    uint64 private _killReviewGeneration;

    error CanonicalCollision(uint8 field, bytes32 existing);
    error CurrentnessAlreadyRevoked(bytes32 digest);
    error CurrentnessAlreadyUsed(bytes32 digest);
    error CurrentnessNonceAlreadyUsed(bytes32 nonce);
    error CurrentnessOutsideWindow(uint256 timestamp, uint256 validAfter, uint256 deadline);
    error InvalidBinding(uint8 field);
    error InvalidGrantStatus(GrantStatusV1 status);
    error InvalidReceiptStatus(ReceiptStatusV1 status);
    error InvalidSharedIdentity(address component, bytes32 expected, bytes32 actual);
    error ReentrantCall();
    error Unauthorized(address caller, uint8 role);

    modifier nonReentrant() {
        if (_reentrancyState != 1) revert ReentrantCall();
        _reentrancyState = 2;
        _;
        _reentrancyState = 1;
    }

    constructor(
        address reviewerAuthority,
        address governance,
        address finalityAuthority,
        address indexerAuthority,
        address codec,
        address validator,
        address preflight,
        InitialControlStateV1 memory initialControlState
    ) {
        if (
            !_hasCodeWithoutDelegateCall(reviewerAuthority) || !_hasCodeWithoutDelegateCall(governance)
                || !_hasCodeWithoutDelegateCall(finalityAuthority) || !_hasCodeWithoutDelegateCall(indexerAuthority)
                || !_hasCodeWithoutDelegateCall(codec) || !_hasCodeWithoutDelegateCall(validator)
                || !_hasCodeWithoutDelegateCall(preflight) || reviewerAuthority == governance
                || reviewerAuthority == finalityAuthority || reviewerAuthority == indexerAuthority
                || governance == finalityAuthority || governance == indexerAuthority
                || finalityAuthority == indexerAuthority
                || initialControlState.dependencyBehaviorEvidenceHash == bytes32(0)
                || initialControlState.securityControlHeadHash == bytes32(0) || initialControlState.securityEpoch == 0
                || initialControlState.securityEpochHash == bytes32(0) || initialControlState.policyEpoch == 0
                || initialControlState.policyEpochHash == bytes32(0) || initialControlState.reviewGeneration == 0
                || initialControlState.reviewGenerationHash == bytes32(0)
        ) revert InvalidBinding(1);
        if (
            ProgrammableCompletedGraphAdoptionCompatCodecV1(codec).CODEC_ID_HASH()
                    != keccak256("PROGRAMMABLE_COMPLETED_GRAPH_ADOPTION_COMPAT_CODEC_V1")
                || ProgrammableCompletedGraphAdoptionValidatorV1(validator).VALIDATOR_ID_HASH()
                    != keccak256("PROGRAMMABLE_COMPLETED_GRAPH_ADOPTION_VALIDATOR_V1")
                || address(ProgrammableCompletedGraphAdoptionValidatorV1(validator).CODEC()) != codec
                || ProgrammableCompletedGraphAdoptionPreflightV1(preflight).PREFLIGHT_ID_HASH()
                    != keccak256("PROGRAMMABLE_COMPLETED_GRAPH_ADOPTION_PREFLIGHT_V1")
                || ProgrammableCompletedGraphAdoptionPreflightV1(preflight).CODEC() != codec
        ) revert InvalidBinding(1);
        REVIEWER_AUTHORITY = reviewerAuthority;
        REVIEWER_AUTHORITY_RUNTIME_CODE_HASH = reviewerAuthority.codehash;
        GOVERNANCE = governance;
        GOVERNANCE_RUNTIME_CODE_HASH = governance.codehash;
        FINALITY_AUTHORITY = finalityAuthority;
        FINALITY_AUTHORITY_RUNTIME_CODE_HASH = finalityAuthority.codehash;
        INDEXER_AUTHORITY = indexerAuthority;
        INDEXER_AUTHORITY_RUNTIME_CODE_HASH = indexerAuthority.codehash;
        CODEC = ProgrammableCompletedGraphAdoptionCompatCodecV1(codec);
        CODEC_RUNTIME_CODE_HASH = codec.codehash;
        VALIDATOR = ProgrammableCompletedGraphAdoptionValidatorV1(validator);
        VALIDATOR_RUNTIME_CODE_HASH = validator.codehash;
        PREFLIGHT = ProgrammableCompletedGraphAdoptionPreflightV1(preflight);
        PREFLIGHT_RUNTIME_CODE_HASH = preflight.codehash;
        DEPENDENCY_BEHAVIOR_EVIDENCE_HASH = initialControlState.dependencyBehaviorEvidenceHash;
        bytes32 authorityRolesHash = keccak256(
            abi.encode(
                PREFLIGHT_AUTHORITY_ROLES_TYPEHASH,
                reviewerAuthority,
                reviewerAuthority.codehash,
                governance,
                governance.codehash,
                finalityAuthority,
                finalityAuthority.codehash,
                indexerAuthority,
                indexerAuthority.codehash
            )
        );
        bytes32 coreDependenciesHash = keccak256(
            abi.encode(
                PREFLIGHT_CORE_DEPENDENCIES_TYPEHASH,
                codec,
                codec.codehash,
                validator,
                validator.codehash,
                preflight,
                preflight.codehash
            )
        );
        BASE_RUNTIME_AUTHORITY_BINDING_HASH = keccak256(
            abi.encode(
                PREFLIGHT_BASE_RUNTIME_BINDING_TYPEHASH,
                block.chainid,
                address(this),
                authorityRolesHash,
                coreDependenciesHash,
                initialControlState.dependencyBehaviorEvidenceHash
            )
        );
        _securityControlHeadHash = initialControlState.securityControlHeadHash;
        _securityEpoch = initialControlState.securityEpoch;
        _securityEpochHash = initialControlState.securityEpochHash;
        _policyEpoch = initialControlState.policyEpoch;
        _policyEpochHash = initialControlState.policyEpochHash;
        _reviewGeneration = initialControlState.reviewGeneration;
        _reviewGenerationHash = initialControlState.reviewGenerationHash;
    }

    function registerAdoptionProfileV1(AdoptionProfileCapabilityV1 calldata capability) external override nonReentrant {
        _requireCodec();
        _requireValidator();
        _requireGovernance();
        if (!VALIDATOR.validateProfileCapabilityV1(address(this), capability)) revert InvalidBinding(2);
        _profileCapability[capability.profileKey] = capability;
        _profileCapabilityHash[capability.profileKey] = CODEC.computeAdoptionProfileCapabilityHash(capability);
        _profileRuntimeBindingHash[capability.profileKey] = _runtimeAuthorityBindingHash(capability);
        _profileStatus[capability.profileKey] = ProfileStatusV1.Active;
        emit AdoptionProfileRegisteredV1(capability.profileKey, capability.profileDescriptorHash, capability.policyHash);
        emit AdoptionProfileStatusUpdatedV1(capability.profileKey, ProfileStatusV1.Active);
    }

    function setAdoptionProfileStatusV1(bytes32 profileKey, ProfileStatusV1 status) external override nonReentrant {
        _requireReviewerOrGovernance();
        ProfileStatusV1 current = _profileStatus[profileKey];
        if (
            current == ProfileStatusV1.Invalid || status == ProfileStatusV1.Invalid
                || current == ProfileStatusV1.Deprecated
                || (current == ProfileStatusV1.Active && status == ProfileStatusV1.Active)
                // A suspension permanently invalidates all grants/currentness bound to this exact profile identity.
                // Recovery requires a separately registered profile version and a newly reviewed grant.
                || (current == ProfileStatusV1.Suspended && status != ProfileStatusV1.Deprecated)
        ) revert InvalidBinding(22);
        _profileStatus[profileKey] = status;
        emit AdoptionProfileStatusUpdatedV1(profileKey, status);
    }

    function setGlobalAdoptionKillV1(bool killed) external override nonReentrant {
        _requireReviewerOrGovernance();
        if (killed) {
            _killSecurityEpoch = _securityEpoch;
            _killPolicyEpoch = _policyEpoch;
            _killReviewGeneration = _reviewGeneration;
        } else if (
            !_globalAdoptionKilled || _reviewGeneration <= _killReviewGeneration
                || (_securityEpoch <= _killSecurityEpoch && _policyEpoch <= _killPolicyEpoch)
        ) {
            // A recovery must advance at least one control epoch. That fails closed for all grants/currentness
            // issued before the incident and requires their review/rebind instead of reviving residual permits.
            revert InvalidBinding(23);
        }
        _globalAdoptionKilled = killed;
        emit GlobalAdoptionKillSetV1(killed);
    }

    function activateLaunchGrantV1(LaunchGrantV1 calldata grant, bytes calldata reviewerSignature)
        external
        override
        nonReentrant
        returns (bytes32 digest)
    {
        _requireCodec();
        AdoptionProfileCapabilityV1 memory capability = _profileCapability[grant.profileKey];
        _requireAvailableProfile(grant.profileKey, capability, 3);
        _requireValidator();
        if (!VALIDATOR.validateLaunchGrantV1(address(this), grant, capability)) revert InvalidBinding(6);
        digest = launchGrantDigest(grant);
        bytes32 grantHash = CODEC.computeLaunchGrantHash(grant);
        bytes32 stampLaunchId = CODEC.computeStampLaunchId(
            address(this), grant.launchWallet, grant.profileKey, grant.contractPlanHash, grant.sourceLaunchId
        );
        if (
            grant.antiReplayNonce == grant.sourceLaunchId || grant.antiReplayNonce == stampLaunchId
                || grant.sourceLaunchId == stampLaunchId
        ) revert InvalidBinding(24);
        if (!_isValidAuthoritySignature(digest, reviewerSignature)) revert InvalidBinding(3);
        if (_grantStatus[digest] != GrantStatusV1.None || _receiptStatus[stampLaunchId] != ReceiptStatusV1.None) {
            revert CanonicalCollision(1, stampLaunchId);
        }
        _reserveWinner(grant.antiReplayNonce, grant.winnerKeyHash, digest);
        _grantHash[digest] = grantHash;
        _stampLaunchIdByGrantDigest[digest] = stampLaunchId;
        _grantStatus[digest] = GrantStatusV1.Active;
        _receiptStatus[stampLaunchId] = ReceiptStatusV1.Prepared;
        emit LaunchGrantActivatedV1(
            stampLaunchId, digest, grant.launchWallet, grant.antiReplayNonce, grant.winnerKeyHash
        );
    }

    function revokeLaunchGrantV1(bytes32 digest) external override nonReentrant {
        _requireReviewerOrGovernance();
        if (_grantStatus[digest] != GrantStatusV1.Active) revert InvalidGrantStatus(_grantStatus[digest]);
        _grantStatus[digest] = GrantStatusV1.Revoked;
        emit LaunchGrantRevokedV1(_stampLaunchIdByGrantDigest[digest], digest);
    }

    function revokeExecutionCurrentnessV1(bytes32 digest) external override nonReentrant {
        _requireReviewerOrGovernance();
        if (digest == bytes32(0) || _usedCurrentnessDigest[digest] || _revokedCurrentnessDigest[digest]) {
            revert InvalidBinding(20);
        }
        _revokedCurrentnessDigest[digest] = true;
        emit ExecutionCurrentnessRevokedV1(digest);
    }

    function advanceSecurityPolicyEpochsV1(
        bytes32 securityControlHeadHash,
        uint64 securityEpoch,
        bytes32 securityEpochHash,
        uint64 policyEpoch,
        bytes32 policyEpochHash,
        uint64 reviewGeneration,
        bytes32 reviewGenerationHash
    ) external override nonReentrant {
        _requireGovernance();
        if (
            securityControlHeadHash == bytes32(0) || securityEpoch < _securityEpoch || policyEpoch < _policyEpoch
                || securityEpochHash == bytes32(0) || policyEpochHash == bytes32(0)
                || (securityEpoch == _securityEpoch && securityEpochHash != _securityEpochHash)
                || (policyEpoch == _policyEpoch && policyEpochHash != _policyEpochHash)
                || (securityEpoch == _securityEpoch && policyEpoch == _policyEpoch)
                || reviewGeneration <= _reviewGeneration || reviewGenerationHash == bytes32(0)
        ) revert InvalidBinding(4);
        _securityControlHeadHash = securityControlHeadHash;
        _securityEpoch = securityEpoch;
        _securityEpochHash = securityEpochHash;
        _policyEpoch = policyEpoch;
        _policyEpochHash = policyEpochHash;
        _reviewGeneration = reviewGeneration;
        _reviewGenerationHash = reviewGenerationHash;
        emit SecurityPolicyReviewControlsAdvancedV1(
            securityControlHeadHash,
            securityEpoch,
            securityEpochHash,
            policyEpoch,
            policyEpochHash,
            reviewGeneration,
            reviewGenerationHash
        );
    }

    function adoptCompletedGraphV1(CompletedGraphAdoptionV1 calldata adoption)
        external
        override
        nonReentrant
        returns (bytes32 coreHash)
    {
        _requireCodec();
        AdoptionProfileCapabilityV1 memory capability = _profileCapability[adoption.plan.profileKey];
        bytes32 planHash = CODEC.computePlanHash(adoption.plan);
        bytes32 grantDigest = launchGrantDigest(adoption.grant);
        bytes32 stampLaunchId = CODEC.computeStampLaunchId(
            address(this), adoption.plan.launchWallet, adoption.plan.profileKey, planHash, adoption.plan.sourceLaunchId
        );
        _requireValidator();
        if (!VALIDATOR.validateAdoptionEnvelopeV1(
                address(this),
                msg.sender,
                adoption.grant,
                capability,
                adoption.plan,
                adoption.request,
                grantDigest,
                planHash,
                stampLaunchId
            )) revert InvalidBinding(7);
        _validateCompletedGraph(adoption, capability);
        bytes32 currentnessDigest = _validateCurrentness(adoption, capability, grantDigest, planHash);
        _reserveComponents(adoption.plan, adoption.components, stampLaunchId);
        _consumeCurrentness(adoption.currentness, currentnessDigest);
        _grantStatus[grantDigest] = GrantStatusV1.Consumed;
        coreHash = _recordAdoption(
            adoption.grant, adoption.request, grantDigest, currentnessDigest, stampLaunchId, planHash, capability
        );
        emit LaunchGrantConsumedV1(stampLaunchId, grantDigest);
        emit CanonicalReceiptAdoptedV1(stampLaunchId, coreHash, grantDigest);
    }

    function advanceFinalityIndexingV1(FinalityIndexingReceiptV1 calldata receipt) external override nonReentrant {
        _requireCodec();
        ReceiptStatusV1 current = _receiptStatus[receipt.stampLaunchId];
        bool finalizing = current == ReceiptStatusV1.Adopted && receipt.nextStatus == ReceiptStatusV1.Finalized;
        bool indexing = current == ReceiptStatusV1.Finalized && receipt.nextStatus == ReceiptStatusV1.Indexed;
        bool publishing = current == ReceiptStatusV1.Indexed && receipt.nextStatus == ReceiptStatusV1.Published;
        if (finalizing) {
            _requireActor(FINALITY_AUTHORITY, FINALITY_AUTHORITY_RUNTIME_CODE_HASH, 3);
        } else if (indexing || publishing) {
            _requireActor(INDEXER_AUTHORITY, INDEXER_AUTHORITY_RUNTIME_CODE_HASH, 4);
        } else {
            revert InvalidReceiptStatus(current);
        }
        CanonicalReceiptCoreV1 storage core = _canonicalReceiptCore[receipt.stampLaunchId];
        if (
            receipt.receiptCoreHash != core.receiptCoreHash || receipt.launchGrantDigest != core.launchGrantDigest
                || receipt.previousFinalityIndexingReceiptHash != _finalityIndexingReceiptHash[receipt.stampLaunchId]
                || receipt.finalityIndexingReceiptHash == bytes32(0)
                || receipt.finalityIndexingReceiptHash == receipt.previousFinalityIndexingReceiptHash
                || receipt.evidenceHash == bytes32(0)
                || CODEC.computeFinalityIndexingReceiptHash(receipt) != receipt.finalityIndexingReceiptHash
        ) revert InvalidBinding(5);
        _finalityIndexingReceiptHash[receipt.stampLaunchId] = receipt.finalityIndexingReceiptHash;
        _receiptStatus[receipt.stampLaunchId] = receipt.nextStatus;
        emit FinalityIndexingAdvancedV1(
            receipt.stampLaunchId, receipt.nextStatus, receipt.finalityIndexingReceiptHash, receipt.evidenceHash
        );
    }

    function launchGrantDigest(LaunchGrantV1 calldata grant) public view override returns (bytes32) {
        _requireCodec();
        return _hashTypedDataV4(CODEC.computeLaunchGrantStructHash(grant));
    }

    function executionCurrentnessDigest(ExecutionCurrentnessV1 calldata currentness)
        public
        view
        override
        returns (bytes32)
    {
        _requireCodec();
        return _hashTypedDataV4(CODEC.computeExecutionCurrentnessStructHash(currentness));
    }

    function preflightControlStateV1(bytes32 profileKey)
        external
        view
        override
        returns (AdoptionPreflightControlStateV1 memory state)
    {
        AdoptionProfileCapabilityV1 storage capability = _profileCapability[profileKey];
        state.runtimeAuthorityBindingHash = _profileRuntimeBindingHash[profileKey];
        if (REVIEWER_AUTHORITY.codehash == REVIEWER_AUTHORITY_RUNTIME_CODE_HASH) {
            state.liveRuntimeMask |= RUNTIME_REVIEWER;
        }
        if (GOVERNANCE.codehash == GOVERNANCE_RUNTIME_CODE_HASH) state.liveRuntimeMask |= RUNTIME_GOVERNANCE;
        if (FINALITY_AUTHORITY.codehash == FINALITY_AUTHORITY_RUNTIME_CODE_HASH) {
            state.liveRuntimeMask |= RUNTIME_FINALITY;
        }
        if (INDEXER_AUTHORITY.codehash == INDEXER_AUTHORITY_RUNTIME_CODE_HASH) {
            state.liveRuntimeMask |= RUNTIME_INDEXER;
        }
        if (address(CODEC).codehash == CODEC_RUNTIME_CODE_HASH) state.liveRuntimeMask |= RUNTIME_CODEC;
        if (address(VALIDATOR).codehash == VALIDATOR_RUNTIME_CODE_HASH) state.liveRuntimeMask |= RUNTIME_VALIDATOR;
        if (address(PREFLIGHT).codehash == PREFLIGHT_RUNTIME_CODE_HASH) state.liveRuntimeMask |= RUNTIME_PREFLIGHT;
        if (
            capability.stateVerifierBinding.stateVerifier.codehash
                == capability.stateVerifierBinding.stateVerifierRuntimeCodeHash
        ) state.liveRuntimeMask |= RUNTIME_STATE_VERIFIER;
        bool noPoolBinding = capability.canonicalPoolManager == address(0)
            && capability.canonicalPoolManagerRuntimeCodeHash == bytes32(0)
            && capability.canonicalPoolManagerChainId == 0;
        if (
            noPoolBinding
                || (capability.canonicalPoolManagerChainId == block.chainid
                    && capability.canonicalPoolManager.codehash == capability.canonicalPoolManagerRuntimeCodeHash)
        ) state.liveRuntimeMask |= RUNTIME_POOL_MANAGER;
        state.dependencyBehaviorEvidenceHash = DEPENDENCY_BEHAVIOR_EVIDENCE_HASH;
        state.securityControlHeadHash = _securityControlHeadHash;
        state.securityEpoch = _securityEpoch;
        state.securityEpochHash = _securityEpochHash;
        state.policyEpoch = _policyEpoch;
        state.policyEpochHash = _policyEpochHash;
        state.reviewControl.reviewGeneration = _reviewGeneration;
        state.reviewControl.reviewGenerationHash = _reviewGenerationHash;
        state.globalAdoptionKilled = _globalAdoptionKilled;
        state.profileStatus = _profileStatus[profileKey];
        state.profileCapabilityHash = _profileCapabilityHash[profileKey];
    }

    function preflightGrantReceiptStateV1(AdoptionPreflightQueryV1 calldata query, bytes32 candidateCurrentnessDigest)
        external
        view
        override
        returns (AdoptionPreflightGrantReceiptStateV1 memory state)
    {
        state.grantStateHead = _launchGrantStateHead(query.launchGrantDigest);
        state.winnerNonceOccupantGrantDigest = _grantDigestByWinnerNonce[query.antiReplayNonce];
        state.winnerKeyOccupantGrantDigest = _grantDigestByWinnerKeyHash[query.winnerKeyHash];
        state.currentnessRevoked = _revokedCurrentnessDigest[candidateCurrentnessDigest];
        state.currentnessUsed = _usedCurrentnessDigest[candidateCurrentnessDigest];
        state.currentnessNonceUsed = _usedCurrentnessNonce[query.currentnessNonce];
        state.receiptStatus = _receiptStatus[query.stampLaunchId];
        state.receiptCoreHash = _canonicalReceiptCore[query.stampLaunchId].receiptCoreHash;
        state.finalityIndexingReceiptHash = _finalityIndexingReceiptHash[query.stampLaunchId];
        state.graphOccupantStampLaunchId = _stampLaunchIdByGraphHash[query.componentGraphHash];
        state.exclusiveTokenOccupantStampLaunchId = _stampLaunchIdByExclusiveToken[query.exclusiveToken];
        state.poolOccupantStampLaunchId = _stampLaunchIdByPool[keccak256(abi.encode(query.poolManager, query.poolId))];
    }

    function preflightComponentStateV1(address component)
        external
        view
        override
        returns (AdoptionPreflightComponentStateV1 memory state)
    {
        state.exclusiveComponentOccupantStampLaunchId = _exclusiveComponentStampLaunchId[component];
        state.sharedComponentIdentityHash = _sharedComponentIdentityHash[component];
        state.actualComponentRuntimeCodeHash = component.codehash;
    }

    function canonicalReceiptCore(bytes32 stampLaunchId)
        external
        view
        override
        returns (CanonicalReceiptCoreV1 memory)
    {
        return _canonicalReceiptCore[stampLaunchId];
    }

    function _reserveComponents(
        CompletedGraphPlanV1 calldata plan,
        ComponentV1[] calldata components,
        bytes32 stampLaunchId
    ) private {
        bool tokenExclusive;
        for (uint256 i; i < components.length; ++i) {
            ComponentV1 calldata component = components[i];
            _reserveComponent(component, stampLaunchId);
            emit CanonicalComponentRecordedV1(
                stampLaunchId,
                // i is bounded by the Validator-enforced MAX_COMPONENTS value of 24.
                // forge-lint: disable-next-line(unsafe-typecast)
                uint8(i),
                component.account,
                component.kind,
                component.scope,
                component.deploymentKind,
                component.runtimeCodeHash,
                component.configurationHash,
                component.creationEvidenceHash
            );
            if (
                component.kind == ComponentKindV1.Token && component.account == plan.identities.token
                    && component.scope == ComponentScopeV1.Exclusive
            ) tokenExclusive = true;
        }
        if (tokenExclusive) {
            bytes32 existing = _stampLaunchIdByExclusiveToken[plan.identities.token];
            if (existing != bytes32(0)) revert CanonicalCollision(5, existing);
            _stampLaunchIdByExclusiveToken[plan.identities.token] = stampLaunchId;
        }
        if ((plan.identityMask & IDENTITY_POOL) != 0) {
            bytes32 poolKey = keccak256(abi.encode(plan.poolManager, plan.poolId));
            bytes32 existingPool = _stampLaunchIdByPool[poolKey];
            if (existingPool != bytes32(0)) revert CanonicalCollision(6, existingPool);
            _stampLaunchIdByPool[poolKey] = stampLaunchId;
        }
        bytes32 existingGraph = _stampLaunchIdByGraphHash[plan.componentGraphHash];
        if (existingGraph != bytes32(0)) revert CanonicalCollision(7, existingGraph);
        _stampLaunchIdByGraphHash[plan.componentGraphHash] = stampLaunchId;
    }

    function _validateCompletedGraph(
        CompletedGraphAdoptionV1 calldata adoption,
        AdoptionProfileCapabilityV1 memory capability
    ) private view {
        VALIDATOR.validateCompletedGraphV1(
            address(this),
            capability,
            adoption.plan,
            adoption.grant.sourceCommitHash,
            adoption.grant.sourceTreeHash,
            adoption.components,
            adoption.edges,
            adoption.request
        );
    }

    function _validateCurrentness(
        CompletedGraphAdoptionV1 calldata adoption,
        AdoptionProfileCapabilityV1 memory capability,
        bytes32 grantDigest,
        bytes32 planHash
    ) private view returns (bytes32 digest) {
        CompletedGraphPlanV1 calldata plan = adoption.plan;
        ExecutionCurrentnessV1 calldata currentness = adoption.currentness;
        bytes32 requestHash = CODEC.computeAdoptionRequestHash(adoption.request);
        _requirePreflight();
        bytes32 expectedPreflightReadbackHash =
            PREFLIGHT.computeAdoptionPreflightAggregateV1(address(this), adoption, capability, grantDigest, planHash);
        if (
            currentness.chainId != block.chainid || currentness.registry != address(this)
                || currentness.launchWallet != plan.launchWallet || currentness.launchGrantDigest != grantDigest
                || currentness.contractPlanHash != planHash || currentness.receiptRequestHash != requestHash
                || currentness.preflightReadbackHash != expectedPreflightReadbackHash
                || currentness.simulationEvidenceHash == bytes32(0)
                || currentness.serviceDeploymentBindingHash == bytes32(0)
                || currentness.dualProviderQuorumEvidenceHash == bytes32(0)
                || currentness.expectedResultHash != plan.resultHash
                || currentness.adoptionIntentHash != plan.adoptionIntentHash
                || currentness.securityControlHeadHash != _securityControlHeadHash
                || currentness.securityEpoch != _securityEpoch || currentness.securityEpochHash != _securityEpochHash
                || currentness.policyEpoch != _policyEpoch || currentness.policyEpochHash != _policyEpochHash
                || currentness.reviewControl.reviewGeneration != _reviewGeneration
                || currentness.reviewControl.reviewGenerationHash != _reviewGenerationHash
                || currentness.nonce == bytes32(0)
        ) revert InvalidBinding(16);
        uint256 timestamp = block.timestamp;
        if (
            currentness.validAfter > currentness.deadline || timestamp < currentness.validAfter
                || timestamp > currentness.deadline
        ) revert CurrentnessOutsideWindow(timestamp, currentness.validAfter, currentness.deadline);
        if (currentness.deadline - currentness.validAfter > MAX_CURRENTNESS_LIFETIME) revert InvalidBinding(16);
        digest = executionCurrentnessDigest(currentness);
        if (_revokedCurrentnessDigest[digest]) revert CurrentnessAlreadyRevoked(digest);
        if (_usedCurrentnessDigest[digest]) revert CurrentnessAlreadyUsed(digest);
        if (_usedCurrentnessNonce[currentness.nonce]) revert CurrentnessNonceAlreadyUsed(currentness.nonce);
        if (!_isValidAuthoritySignature(digest, adoption.currentnessSignature)) revert InvalidBinding(16);
    }

    function _runtimeAuthorityBindingHash(AdoptionProfileCapabilityV1 memory capability)
        private
        view
        returns (bytes32)
    {
        bytes32 profileRuntimeBindingHash = keccak256(
            abi.encode(
                PREFLIGHT_PROFILE_RUNTIME_BINDING_TYPEHASH,
                capability.stateVerifierBinding.stateVerifier,
                capability.stateVerifierBinding.stateVerifierRuntimeCodeHash,
                capability.canonicalPoolManagerChainId,
                capability.canonicalPoolManager,
                capability.canonicalPoolManagerRuntimeCodeHash
            )
        );
        return keccak256(
            abi.encode(
                PREFLIGHT_RUNTIME_AUTHORITY_BINDING_TYPEHASH,
                BASE_RUNTIME_AUTHORITY_BINDING_HASH,
                profileRuntimeBindingHash
            )
        );
    }

    function _launchGrantStateHead(bytes32 digest) private view returns (LaunchGrantStateHeadV1 memory head) {
        head.grantDigest = digest;
        head.grantHash = _grantHash[digest];
        head.stampLaunchId = _stampLaunchIdByGrantDigest[digest];
        head.status = _grantStatus[digest];
        head.stateHeadHash = _stateHeadHash(digest, head.grantHash, head.stampLaunchId, head.status);
    }

    function _consumeCurrentness(ExecutionCurrentnessV1 calldata currentness, bytes32 digest) private {
        _usedCurrentnessDigest[digest] = true;
        _usedCurrentnessNonce[currentness.nonce] = true;
    }

    function _recordAdoption(
        LaunchGrantV1 calldata grant,
        AdoptionRequestV1 calldata request,
        bytes32 grantDigest,
        bytes32 currentnessDigest,
        bytes32 stampLaunchId,
        bytes32 planHash,
        AdoptionProfileCapabilityV1 memory capability
    ) private returns (bytes32 coreHash) {
        CanonicalReceiptCoreV1 memory core;
        core.stampLaunchId = stampLaunchId;
        core.sourceLaunchId = grant.sourceLaunchId;
        core.launchGrantDigest = grantDigest;
        core.launchGrantHash = CODEC.computeLaunchGrantHash(grant);
        core.executionCurrentnessDigest = currentnessDigest;
        core.contractPlanHash = planHash;
        core.profileCapabilityHash = CODEC.computeAdoptionProfileCapabilityHash(capability);
        core.adoptionRequestHash = CODEC.computeAdoptionRequestHash(request);
        coreHash = CODEC.computeCanonicalReceiptCoreHash(core);
        core.receiptCoreHash = coreHash;
        _canonicalReceiptCore[stampLaunchId] = core;
        _receiptStatus[stampLaunchId] = ReceiptStatusV1.Adopted;
    }

    function _reserveWinner(bytes32 nonce, bytes32 winnerKeyHash, bytes32 digest) private {
        if (_grantDigestByWinnerNonce[nonce] != bytes32(0)) {
            revert CanonicalCollision(2, _grantDigestByWinnerNonce[nonce]);
        }
        if (_grantDigestByWinnerKeyHash[winnerKeyHash] != bytes32(0)) {
            revert CanonicalCollision(3, _grantDigestByWinnerKeyHash[winnerKeyHash]);
        }
        _grantDigestByWinnerNonce[nonce] = digest;
        _grantDigestByWinnerKeyHash[winnerKeyHash] = digest;
    }

    function _reserveComponent(ComponentV1 calldata component, bytes32 stampLaunchId) private {
        bytes32 exclusive = _exclusiveComponentStampLaunchId[component.account];
        bytes32 sharedIdentity = _sharedComponentIdentityHash[component.account];
        if (component.scope == ComponentScopeV1.Exclusive) {
            if (exclusive != bytes32(0)) revert CanonicalCollision(4, exclusive);
            if (sharedIdentity != bytes32(0)) {
                revert InvalidSharedIdentity(component.account, bytes32(0), sharedIdentity);
            }
            _exclusiveComponentStampLaunchId[component.account] = stampLaunchId;
        } else if (component.scope == ComponentScopeV1.SharedInfrastructure) {
            if (exclusive != bytes32(0)) revert CanonicalCollision(4, exclusive);
            bytes32 identityHash = CODEC.computeSharedComponentIdentityHash(component);
            if (sharedIdentity != bytes32(0) && sharedIdentity != identityHash) {
                revert InvalidSharedIdentity(component.account, sharedIdentity, identityHash);
            }
            _sharedComponentIdentityHash[component.account] = identityHash;
        } else {
            revert InvalidBinding(17);
        }
    }

    function _isValidAuthoritySignature(bytes32 digest, bytes calldata signature) private view returns (bool valid) {
        if (
            signature.length > MAX_SIGNATURE_BYTES
                || REVIEWER_AUTHORITY.codehash != REVIEWER_AUTHORITY_RUNTIME_CODE_HASH
        ) {
            return false;
        }
        bytes memory data = abi.encodeWithSelector(IERC1271CompatV1.isValidSignature.selector, digest, signature);
        bytes memory result = new bytes(32);
        bool success;
        uint256 returnDataSize;
        address authority = REVIEWER_AUTHORITY;
        uint256 callGas = gasleft();
        if (callGas <= AUTHORITY_GAS_RESERVE) return false;
        unchecked {
            callGas -= AUTHORITY_GAS_RESERVE;
        }
        if (callGas > MAX_AUTHORITY_STATICCALL_GAS) callGas = MAX_AUTHORITY_STATICCALL_GAS;
        assembly ("memory-safe") {
            success := staticcall(callGas, authority, add(data, 0x20), mload(data), add(result, 0x20), 32)
            returnDataSize := returndatasize()
        }
        if (!success || returnDataSize != 32) return false;
        return bytes4(abi.decode(result, (bytes32))) == ERC1271_MAGICVALUE;
    }

    function _hashTypedDataV4(bytes32 structHash) private view returns (bytes32) {
        bytes32 domainSeparator = keccak256(
            abi.encode(EIP712_DOMAIN_TYPEHASH, EIP712_NAME_HASH, EIP712_VERSION_HASH, block.chainid, address(this))
        );
        return keccak256(abi.encodePacked("\x19\x01", domainSeparator, structHash));
    }

    function _stateHeadHash(bytes32 digest, bytes32 grantHash, bytes32 stampLaunchId, GrantStatusV1 status)
        private
        pure
        returns (bytes32)
    {
        return keccak256(abi.encode(GRANT_STATE_HEAD_TYPEHASH, digest, grantHash, stampLaunchId, uint8(status)));
    }

    function _requireReviewerOrGovernance() private view {
        bool reviewer =
            msg.sender == REVIEWER_AUTHORITY && REVIEWER_AUTHORITY.codehash == REVIEWER_AUTHORITY_RUNTIME_CODE_HASH;
        bool governance = msg.sender == GOVERNANCE && GOVERNANCE.codehash == GOVERNANCE_RUNTIME_CODE_HASH;
        if (!reviewer && !governance) revert Unauthorized(msg.sender, 2);
    }

    function _requireGovernance() private view {
        _requireActor(GOVERNANCE, GOVERNANCE_RUNTIME_CODE_HASH, 1);
    }

    function _requireActor(address actor, bytes32 runtimeCodeHash, uint8 role) private view {
        if (msg.sender != actor || actor.codehash != runtimeCodeHash) revert Unauthorized(msg.sender, role);
    }

    function _requireCodec() private view {
        if (address(CODEC).codehash != CODEC_RUNTIME_CODE_HASH) revert InvalidBinding(19);
    }

    function _requireValidator() private view {
        if (address(VALIDATOR).codehash != VALIDATOR_RUNTIME_CODE_HASH) revert InvalidBinding(21);
    }

    function _requirePreflight() private view {
        if (address(PREFLIGHT).codehash != PREFLIGHT_RUNTIME_CODE_HASH) revert InvalidBinding(22);
    }

    function _requireAvailableProfile(bytes32 profileKey, AdoptionProfileCapabilityV1 memory capability, uint8 field)
        private
        view
    {
        if (
            _globalAdoptionKilled || _profileStatus[profileKey] != ProfileStatusV1.Active || !capability.enabled
                || capability.admissionStatus != AdmissionStatusV1.Admitted
                || capability.reviewControl.reviewGeneration != _reviewGeneration
                || capability.reviewControl.reviewGenerationHash != _reviewGenerationHash
        ) revert InvalidBinding(field);
    }

    /// @dev This detects only a DELEGATECALL opcode in the supplied runtime. It does not prove that CALL/STATICCALL
    ///      forwarding or downstream behavior is immutable; constructor/profile evidence hashes cover that review.
    function _hasCodeWithoutDelegateCall(address dependency) private view returns (bool) {
        if (dependency.code.length == 0) return false;
        bytes memory runtime = dependency.code;
        for (uint256 i; i < runtime.length; ++i) {
            uint8 opcode = uint8(runtime[i]);
            if (opcode == 0xf4) return false;
            if (opcode >= 0x60 && opcode <= 0x7f) {
                unchecked {
                    i += opcode - 0x5f;
                }
            }
        }
        return true;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {
    IProgrammableCompletedGraphAdoptionCompatV1,
    IProgrammableCompletedGraphAdoptionPreflightV1
} from "./IProgrammableCompletedGraphAdoptionCompatV1.sol";
import { ProgrammableCompletedGraphAdoptionCompatCodecV1 } from "./ProgrammableCompletedGraphAdoptionCompatCodecV1.sol";

/// @notice Immutable side-effect-free preflight projection for the completed-graph ADOPT Registry.
/// @dev It reads only the exact typed Registry state source, derives canonical hashes with the pinned Codec and has
///      no signing, reservation, execution, target, selector, calldata, value, approval, CREATE or delegatecall path.
contract ProgrammableCompletedGraphAdoptionPreflightV1 is IProgrammableCompletedGraphAdoptionPreflightV1 {
    bytes32 public constant PREFLIGHT_ID_HASH = keccak256("PROGRAMMABLE_COMPLETED_GRAPH_ADOPTION_PREFLIGHT_V1");
    uint16 private constant REQUIRED_RUNTIME_MASK = (1 << 9) - 1;

    address public immutable override CODEC;
    bytes32 public immutable CODEC_RUNTIME_CODE_HASH;

    error InvalidPreflight(uint8 field);

    constructor(address codec) {
        if (
            codec.code.length == 0
                || ProgrammableCompletedGraphAdoptionCompatCodecV1(codec).CODEC_ID_HASH()
                    != keccak256("PROGRAMMABLE_COMPLETED_GRAPH_ADOPTION_COMPAT_CODEC_V1")
        ) revert InvalidPreflight(1);
        CODEC = codec;
        CODEC_RUNTIME_CODE_HASH = codec.codehash;
    }

    function adoptionPreflightReadbackV1(
        address registry,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightQueryV1 calldata query,
        bytes32 candidateCurrentnessDigest
    ) external view override returns (IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightReadbackV1 memory) {
        return _adoptionPreflightReadback(registry, query, candidateCurrentnessDigest);
    }

    function _adoptionPreflightReadback(
        address registry,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightQueryV1 memory query,
        bytes32 candidateCurrentnessDigest
    ) private view returns (IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightReadbackV1 memory r) {
        _requireCodec();
        IProgrammableCompletedGraphAdoptionCompatV1 source = IProgrammableCompletedGraphAdoptionCompatV1(registry);
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightControlStateV1 memory control =
            source.preflightControlStateV1(query.profileKey);
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightGrantReceiptStateV1 memory lifecycle =
            source.preflightGrantReceiptStateV1(query, candidateCurrentnessDigest);
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightComponentStateV1 memory component =
            source.preflightComponentStateV1(query.component);

        r.chainId = block.chainid;
        r.registry = registry;
        r.runtimeAuthorityBindingHash = control.runtimeAuthorityBindingHash;
        r.liveRuntimeMask = control.liveRuntimeMask;
        r.dependencyBehaviorEvidenceHash = control.dependencyBehaviorEvidenceHash;
        r.securityControlHeadHash = control.securityControlHeadHash;
        r.securityEpoch = control.securityEpoch;
        r.securityEpochHash = control.securityEpochHash;
        r.policyEpoch = control.policyEpoch;
        r.policyEpochHash = control.policyEpochHash;
        r.reviewControl = control.reviewControl;
        r.globalAdoptionKilled = control.globalAdoptionKilled;
        r.profileStatus = control.profileStatus;
        r.profileCapabilityHash = control.profileCapabilityHash;
        r.grantStateHead = lifecycle.grantStateHead;
        r.winnerNonceOccupantGrantDigest = lifecycle.winnerNonceOccupantGrantDigest;
        r.winnerKeyOccupantGrantDigest = lifecycle.winnerKeyOccupantGrantDigest;
        r.currentnessRevoked = lifecycle.currentnessRevoked;
        r.currentnessUsed = lifecycle.currentnessUsed;
        r.currentnessNonceUsed = lifecycle.currentnessNonceUsed;
        r.receiptStatus = lifecycle.receiptStatus;
        r.receiptCoreHash = lifecycle.receiptCoreHash;
        r.finalityIndexingReceiptHash = lifecycle.finalityIndexingReceiptHash;
        r.graphOccupantStampLaunchId = lifecycle.graphOccupantStampLaunchId;
        r.exclusiveTokenOccupantStampLaunchId = lifecycle.exclusiveTokenOccupantStampLaunchId;
        r.poolOccupantStampLaunchId = lifecycle.poolOccupantStampLaunchId;
        r.exclusiveComponentOccupantStampLaunchId = component.exclusiveComponentOccupantStampLaunchId;
        r.sharedComponentIdentityHash = component.sharedComponentIdentityHash;
        r.actualComponentRuntimeCodeHash = component.actualComponentRuntimeCodeHash;
        ProgrammableCompletedGraphAdoptionCompatCodecV1 codec = ProgrammableCompletedGraphAdoptionCompatCodecV1(CODEC);
        r.queryHash = codec.computeAdoptionPreflightQueryHash(query);
        r.componentLeafHash = codec.computeAdoptionPreflightComponentLeafHash(
            query,
            r.actualComponentRuntimeCodeHash,
            r.exclusiveComponentOccupantStampLaunchId,
            r.sharedComponentIdentityHash
        );
        r.globalReadbackHeadHash = codec.computeAdoptionPreflightGlobalHeadHash(r);
    }

    function computeAdoptionPreflightAggregateV1(
        address registry,
        IProgrammableCompletedGraphAdoptionCompatV1.CompletedGraphAdoptionV1 calldata adoption,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionProfileCapabilityV1 calldata capability,
        bytes32 grantDigest,
        bytes32 contractPlanHash
    ) external view override returns (bytes32) {
        _requireCodec();
        ProgrammableCompletedGraphAdoptionCompatCodecV1 codec = ProgrammableCompletedGraphAdoptionCompatCodecV1(CODEC);
        if (adoption.components.length == 0 || adoption.components.length > codec.MAX_COMPONENTS()) {
            revert InvalidPreflight(3);
        }

        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightQueryV1 memory query;
        query.profileKey = adoption.plan.profileKey;
        query.launchGrantDigest = grantDigest;
        query.expectedContractPlanHash = contractPlanHash;
        query.stampLaunchId = adoption.request.stampLaunchId;
        query.antiReplayNonce = adoption.grant.antiReplayNonce;
        query.winnerKeyHash = adoption.grant.winnerKeyHash;
        query.componentGraphHash = adoption.plan.componentGraphHash;
        query.exclusiveToken = adoption.plan.identities.token;
        query.poolManager = adoption.plan.poolManager;
        query.poolId = adoption.plan.poolId;
        query.currentnessNonce = adoption.currentness.nonce;

        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightReadbackV1 memory r =
            _adoptionPreflightReadback(registry, query, bytes32(0));
        if (
            r.liveRuntimeMask != REQUIRED_RUNTIME_MASK || r.globalAdoptionKilled
                || r.profileStatus != IProgrammableCompletedGraphAdoptionCompatV1.ProfileStatusV1.Active
                || r.profileCapabilityHash != codec.computeAdoptionProfileCapabilityHash(capability)
                || r.grantStateHead.status != IProgrammableCompletedGraphAdoptionCompatV1.GrantStatusV1.Active
                || r.grantStateHead.grantDigest != grantDigest
                || r.grantStateHead.grantHash != codec.computeLaunchGrantHash(adoption.grant)
                || r.grantStateHead.stampLaunchId != adoption.request.stampLaunchId
                || r.winnerNonceOccupantGrantDigest != grantDigest || r.winnerKeyOccupantGrantDigest != grantDigest
                || r.currentnessNonceUsed
                || r.receiptStatus != IProgrammableCompletedGraphAdoptionCompatV1.ReceiptStatusV1.Prepared
                || r.receiptCoreHash != bytes32(0) || r.finalityIndexingReceiptHash != bytes32(0)
                || r.graphOccupantStampLaunchId != bytes32(0) || r.exclusiveTokenOccupantStampLaunchId != bytes32(0)
                || r.poolOccupantStampLaunchId != bytes32(0)
        ) revert InvalidPreflight(4);

        bytes32[] memory leaves = new bytes32[](adoption.components.length);
        for (uint256 i; i < adoption.components.length; ++i) {
            IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1 calldata component = adoption.components[i];
            // The Codec-enforced component cap is 24, so the index cannot truncate.
            // forge-lint: disable-next-line(unsafe-typecast)
            query.componentIndex = uint8(i);
            query.component = component.account;
            query.componentScope = component.scope;
            query.expectedSharedIdentityHash = component.scope
                == IProgrammableCompletedGraphAdoptionCompatV1.ComponentScopeV1.SharedInfrastructure
                ? codec.computeSharedComponentIdentityHash(component)
                : bytes32(0);
            query.expectedRuntimeCodeHash = component.runtimeCodeHash;
            IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightReadbackV1 memory leaf =
                _adoptionPreflightReadback(registry, query, bytes32(0));
            if (
                leaf.actualComponentRuntimeCodeHash != component.runtimeCodeHash
                    || leaf.exclusiveComponentOccupantStampLaunchId != bytes32(0)
                    || (component.scope == IProgrammableCompletedGraphAdoptionCompatV1.ComponentScopeV1.Exclusive
                        && leaf.sharedComponentIdentityHash != bytes32(0))
                    || (component.scope
                            == IProgrammableCompletedGraphAdoptionCompatV1.ComponentScopeV1.SharedInfrastructure
                        && leaf.sharedComponentIdentityHash != bytes32(0)
                        && leaf.sharedComponentIdentityHash != query.expectedSharedIdentityHash)
            ) revert InvalidPreflight(5);
            leaves[i] = leaf.componentLeafHash;
        }
        return codec.computeAdoptionPreflightReadbackHash(r.globalReadbackHeadHash, keccak256(abi.encodePacked(leaves)));
    }

    function _requireCodec() private view {
        if (CODEC.codehash != CODEC_RUNTIME_CODE_HASH) revert InvalidPreflight(6);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {
    IProgrammableCompletedGraphAdoptionCompatV1,
    IProgrammableCompletedGraphAdoptionStateVerifierV1
} from "./IProgrammableCompletedGraphAdoptionCompatV1.sol";
import { ProgrammableCompletedGraphAdoptionCompatCodecV1 } from "./ProgrammableCompletedGraphAdoptionCompatCodecV1.sol";

/// @notice Stateless, codehash-pinnable validator for the closed completed-graph ADOPT ABI.
/// @dev It has no authority, storage mutations, deployment, target, selector, opaque action, or value surface.
///      The Registry calls its one fixed view function before reserving a canonical receipt.
contract ProgrammableCompletedGraphAdoptionValidatorV1 {
    uint256 public constant MAX_COMPONENTS = 24;
    uint256 public constant MAX_EDGES = 64;

    uint16 public constant IDENTITY_TOKEN = 1 << 0;
    uint16 public constant IDENTITY_HOOK = 1 << 1;
    uint16 public constant IDENTITY_NFT = 1 << 2;
    uint16 public constant IDENTITY_APPLICATION = 1 << 3;
    uint16 public constant IDENTITY_POOL = 1 << 4;
    uint16 public constant IDENTITY_MASK_ALL = (1 << 5) - 1;

    uint256 public constant STATE_VERIFIER_GAS_RESERVE = 200_000;
    uint256 public constant MAX_STATE_VERIFIER_STATICCALL_GAS = 500_000;

    bytes32 public constant VALIDATOR_ID_HASH = keccak256("PROGRAMMABLE_COMPLETED_GRAPH_ADOPTION_VALIDATOR_V1");

    ProgrammableCompletedGraphAdoptionCompatCodecV1 public immutable CODEC;
    bytes32 public immutable CODEC_RUNTIME_CODE_HASH;

    struct RoleScanV1 {
        bool tokenFound;
        bool hookFound;
        bool nftFound;
        bool applicationFound;
    }

    error InvalidBinding(uint8 field);

    constructor(address codec) {
        if (
            codec.code.length == 0 || _containsDelegateCallOpcode(codec)
                || ProgrammableCompletedGraphAdoptionCompatCodecV1(codec).CODEC_ID_HASH()
                    != keccak256("PROGRAMMABLE_COMPLETED_GRAPH_ADOPTION_COMPAT_CODEC_V1")
        ) revert InvalidBinding(1);
        CODEC = ProgrammableCompletedGraphAdoptionCompatCodecV1(codec);
        CODEC_RUNTIME_CODE_HASH = codec.codehash;
    }

    /// @notice Validates one reusable, governance-registered ADOPT capability against the Registry's live controls.
    /// @dev Pure policy lives in this codehash-pinned companion so the state-owning Registry remains deployable.
    function validateProfileCapabilityV1(
        address registry,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionProfileCapabilityV1 calldata capability
    ) external view returns (bool) {
        _requireCodec();
        if (registry == address(0)) return false;
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightControlStateV1 memory control =
            IProgrammableCompletedGraphAdoptionCompatV1(registry).preflightControlStateV1(capability.profileKey);
        bool requiresPool = (capability.requiredIdentityMask & IDENTITY_POOL) != 0;
        bool forbidsPool = (capability.forbiddenIdentityMask & IDENTITY_POOL) != 0;
        bool canonicalPoolConfigured = capability.canonicalPoolManagerChainId != 0
            || capability.canonicalPoolManager != address(0)
            || capability.canonicalPoolManagerRuntimeCodeHash != bytes32(0);
        return capability.profileKey != bytes32(0) && capability.profileDescriptorHash != bytes32(0)
            && capability.exactContractBindingHash != bytes32(0) && capability.routeSchemaHash != bytes32(0)
            && capability.planSchemaArtifactHash != bytes32(0) && capability.policyHash != bytes32(0)
            && capability.stateVerifierBinding.stateVerifier.code.length != 0
            && !_containsDelegateCallOpcode(capability.stateVerifierBinding.stateVerifier)
            && capability.stateVerifierBinding.stateVerifierRuntimeCodeHash != bytes32(0)
            && capability.stateVerifierBinding.stateVerifier.codehash
                == capability.stateVerifierBinding.stateVerifierRuntimeCodeHash
            && capability.stateVerifierBinding.stateSchemaHash != bytes32(0)
            && capability.stateVerifierBinding.stateVerifierBehaviorEvidenceHash != bytes32(0)
            && capability.reviewControl.reviewGeneration == control.reviewControl.reviewGeneration
            && capability.reviewControl.reviewGenerationHash == control.reviewControl.reviewGenerationHash
            && (!canonicalPoolConfigured
                || (capability.canonicalPoolManagerChainId == block.chainid
                    && capability.canonicalPoolManager != address(0)
                    && capability.canonicalPoolManagerRuntimeCodeHash != bytes32(0)))
            && (!requiresPool || canonicalPoolConfigured) && (!forbidsPool || !canonicalPoolConfigured)
            && capability.capabilitySemantics == IProgrammableCompletedGraphAdoptionCompatV1.CapabilitySemanticsV1.Adopt
            && capability.admissionStatus == IProgrammableCompletedGraphAdoptionCompatV1.AdmissionStatusV1.Admitted
            && capability.executionReadiness
                == IProgrammableCompletedGraphAdoptionCompatV1.ExecutionReadinessV1.CompletedGraphAdoptionOnly
            && capability.executionReadinessConstraintHash == CODEC.ADOPTION_ONLY_READINESS_CONSTRAINT_HASH()
            && capability.executionTimeConstraint
                != IProgrammableCompletedGraphAdoptionCompatV1.ExecutionTimeConstraintV1.Invalid
            && (capability.executionTimeConstraint
                    != IProgrammableCompletedGraphAdoptionCompatV1.ExecutionTimeConstraintV1.ExternalExecutionTimeBound
                || capability.executionTimeConstraintEvidenceHash != bytes32(0))
            && (capability.executionTimeConstraint
                    != IProgrammableCompletedGraphAdoptionCompatV1.ExecutionTimeConstraintV1.AdoptionOnlyNoExecution
                || capability.executionTimeConstraintEvidenceHash == bytes32(0))
            && capability.requiredIdentityMask & ~IDENTITY_MASK_ALL == 0
            && capability.forbiddenIdentityMask & ~IDENTITY_MASK_ALL == 0
            && capability.requiredIdentityMask & capability.forbiddenIdentityMask == 0 && capability.enabled
            && control.profileStatus == IProgrammableCompletedGraphAdoptionCompatV1.ProfileStatusV1.Invalid
            && CODEC.computeProfileKey(capability.profileDescriptorHash, capability.routeSchemaHash)
                == capability.profileKey;
    }

    /// @notice Validates the durable grant's immutable review bindings against the live Registry/profile controls.
    function validateLaunchGrantV1(
        address registry,
        IProgrammableCompletedGraphAdoptionCompatV1.LaunchGrantV1 calldata grant,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionProfileCapabilityV1 calldata capability
    ) external view returns (bool) {
        _requireCodec();
        if (registry == address(0)) return false;
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightControlStateV1 memory control =
            IProgrammableCompletedGraphAdoptionCompatV1(registry).preflightControlStateV1(grant.profileKey);
        return grant.chainId == block.chainid && grant.registry == registry && grant.launchWallet != address(0)
            && grant.applicantIdHash != bytes32(0) && grant.profileKey == capability.profileKey
            && grant.profileDescriptorHash == capability.profileDescriptorHash
            && grant.exactContractBindingHash == capability.exactContractBindingHash
            && grant.contractPlanHash != bytes32(0) && grant.applicantPlanArtifactHash != bytes32(0)
            && grant.adoptionIntentHash != bytes32(0)
            && grant.executionReadiness
                == IProgrammableCompletedGraphAdoptionCompatV1.ExecutionReadinessV1.CompletedGraphAdoptionOnly
            && grant.executionReadiness == capability.executionReadiness
            && grant.executionReadinessConstraintHash == capability.executionReadinessConstraintHash
            && grant.executionTimeConstraint
                != IProgrammableCompletedGraphAdoptionCompatV1.ExecutionTimeConstraintV1.Invalid
            && grant.executionTimeConstraint == capability.executionTimeConstraint
            && grant.executionTimeConstraintEvidenceHash == capability.executionTimeConstraintEvidenceHash
            && (grant.executionTimeConstraint
                    != IProgrammableCompletedGraphAdoptionCompatV1.ExecutionTimeConstraintV1.ExternalExecutionTimeBound
                || grant.executionTimeConstraintEvidenceHash != bytes32(0))
            && (grant.executionTimeConstraint
                    != IProgrammableCompletedGraphAdoptionCompatV1.ExecutionTimeConstraintV1.AdoptionOnlyNoExecution
                || grant.executionTimeConstraintEvidenceHash == bytes32(0)) && grant.sourceRepositoryHash != bytes32(0)
            && grant.sourceCommitHash != bytes32(0) && grant.sourceTreeHash != bytes32(0)
            && grant.sourceLaunchId != bytes32(0) && grant.componentGraphHash != bytes32(0)
            && grant.exactRuntimeSetHash != bytes32(0) && grant.componentConfigurationSetHash != bytes32(0)
            && grant.revenueBindingHash == bytes32(0) && grant.resultHash != bytes32(0)
            && grant.builderEvidenceHash != bytes32(0) && grant.reviewerAttestationHash != bytes32(0)
            && grant.securityControlHeadHash == control.securityControlHeadHash
            && grant.securityEpochHash == control.securityEpochHash && grant.policyHash == capability.policyHash
            && grant.policyEpochHash == control.policyEpochHash && grant.securityEpoch == control.securityEpoch
            && grant.policyEpoch == control.policyEpoch
            && grant.reviewControl.reviewGeneration == control.reviewControl.reviewGeneration
            && grant.reviewControl.reviewGenerationHash == control.reviewControl.reviewGenerationHash
            && grant.reviewControl.reviewGeneration == capability.reviewControl.reviewGeneration
            && grant.reviewControl.reviewGenerationHash == capability.reviewControl.reviewGenerationHash
            && grant.antiReplayNonce != bytes32(0) && grant.winnerKeyHash != bytes32(0)
            && grant.winnerKeyHash == CODEC.computeWinnerKeyHash(grant);
    }

    /// @notice Validates the closed grant/plan/request envelope and its live Registry lifecycle state.
    function validateAdoptionEnvelopeV1(
        address registry,
        address launchCaller,
        IProgrammableCompletedGraphAdoptionCompatV1.LaunchGrantV1 calldata grant,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionProfileCapabilityV1 calldata capability,
        IProgrammableCompletedGraphAdoptionCompatV1.CompletedGraphPlanV1 calldata plan,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionRequestV1 calldata request,
        bytes32 grantDigest,
        bytes32 planHash,
        bytes32 stampLaunchId
    ) external view returns (bool) {
        _requireCodec();
        if (registry == address(0)) return false;
        IProgrammableCompletedGraphAdoptionCompatV1 source = IProgrammableCompletedGraphAdoptionCompatV1(registry);
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightControlStateV1 memory control =
            source.preflightControlStateV1(plan.profileKey);
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightQueryV1 memory query;
        query.launchGrantDigest = grantDigest;
        query.stampLaunchId = stampLaunchId;
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightGrantReceiptStateV1 memory lifecycle =
            source.preflightGrantReceiptStateV1(query, bytes32(0));
        return _validAdoptionProfileAndPlan(launchCaller, capability, plan, control)
            && _validAdoptionGrantPlan(
            grant, capability, plan, control, lifecycle, grantDigest, planHash, stampLaunchId
        ) && request.stampLaunchId == stampLaunchId && request.profileKey == plan.profileKey
            && request.componentGraphHash == plan.componentGraphHash && request.resultHash == plan.resultHash
            && request.currentArchitectureStateHash != bytes32(0)
            && ((plan.identityMask & IDENTITY_POOL) != 0) == (request.currentPoolStateHash != bytes32(0))
            && request.currentRevenueStateHash == bytes32(0);
    }

    function _validAdoptionProfileAndPlan(
        address launchCaller,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionProfileCapabilityV1 calldata capability,
        IProgrammableCompletedGraphAdoptionCompatV1.CompletedGraphPlanV1 calldata plan,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightControlStateV1 memory control
    ) private pure returns (bool) {
        return launchCaller == plan.launchWallet && !control.globalAdoptionKilled
            && control.profileStatus == IProgrammableCompletedGraphAdoptionCompatV1.ProfileStatusV1.Active
            && capability.enabled
            && capability.capabilitySemantics == IProgrammableCompletedGraphAdoptionCompatV1.CapabilitySemanticsV1.Adopt
            && capability.admissionStatus == IProgrammableCompletedGraphAdoptionCompatV1.AdmissionStatusV1.Admitted
            && capability.executionReadiness
                == IProgrammableCompletedGraphAdoptionCompatV1.ExecutionReadinessV1.CompletedGraphAdoptionOnly
            && plan.profileDescriptorHash == capability.profileDescriptorHash
            && plan.exactContractBindingHash == capability.exactContractBindingHash
            && plan.routeSchemaHash == capability.routeSchemaHash
            && plan.planSchemaArtifactHash == capability.planSchemaArtifactHash
            && plan.policyHash == capability.policyHash && plan.launchClassification == capability.launchClassification
            && plan.identityMask & ~IDENTITY_MASK_ALL == 0
            && plan.identityMask & capability.requiredIdentityMask == capability.requiredIdentityMask
            && plan.identityMask & capability.forbiddenIdentityMask == 0 && plan.adoptionIntentHash != bytes32(0)
            && plan.executionReadiness
                == IProgrammableCompletedGraphAdoptionCompatV1.ExecutionReadinessV1.CompletedGraphAdoptionOnly
            && plan.executionReadiness == capability.executionReadiness
            && plan.executionReadinessConstraintHash == capability.executionReadinessConstraintHash
            && plan.executionTimeConstraint
                != IProgrammableCompletedGraphAdoptionCompatV1.ExecutionTimeConstraintV1.Invalid
            && plan.executionTimeConstraint == capability.executionTimeConstraint
            && plan.executionTimeConstraintEvidenceHash == capability.executionTimeConstraintEvidenceHash
            && (plan.executionTimeConstraint
                    != IProgrammableCompletedGraphAdoptionCompatV1.ExecutionTimeConstraintV1.ExternalExecutionTimeBound
                || plan.executionTimeConstraintEvidenceHash != bytes32(0))
            && (plan.executionTimeConstraint
                    != IProgrammableCompletedGraphAdoptionCompatV1.ExecutionTimeConstraintV1.AdoptionOnlyNoExecution
                || plan.executionTimeConstraintEvidenceHash == bytes32(0)) && plan.manifestHash != bytes32(0)
            && plan.compilerArtifactHash != bytes32(0) && plan.applicantPlanArtifactHash != bytes32(0)
            && plan.componentGraphHash != bytes32(0) && plan.exactRuntimeSetHash != bytes32(0)
            && plan.componentConfigurationSetHash != bytes32(0) && plan.configurationHash != bytes32(0)
            && plan.revenueBindingHash == bytes32(0) && plan.architectureResultHash != bytes32(0)
            && plan.deploymentLineageHash != bytes32(0) && plan.resultHash != bytes32(0);
    }

    function _validAdoptionGrantPlan(
        IProgrammableCompletedGraphAdoptionCompatV1.LaunchGrantV1 calldata grant,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionProfileCapabilityV1 calldata capability,
        IProgrammableCompletedGraphAdoptionCompatV1.CompletedGraphPlanV1 calldata plan,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightControlStateV1 memory control,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionPreflightGrantReceiptStateV1 memory lifecycle,
        bytes32 grantDigest,
        bytes32 planHash,
        bytes32 stampLaunchId
    ) private view returns (bool) {
        return lifecycle.grantStateHead.status == IProgrammableCompletedGraphAdoptionCompatV1.GrantStatusV1.Active
            && lifecycle.grantStateHead.stampLaunchId == stampLaunchId
            && lifecycle.receiptStatus == IProgrammableCompletedGraphAdoptionCompatV1.ReceiptStatusV1.Prepared
            && lifecycle.grantStateHead.grantHash == CODEC.computeLaunchGrantHash(grant)
            && lifecycle.grantStateHead.grantDigest == grantDigest && grant.contractPlanHash == planHash
            && grant.applicantPlanArtifactHash == plan.applicantPlanArtifactHash
            && grant.adoptionIntentHash == plan.adoptionIntentHash
            && grant.executionReadiness == plan.executionReadiness
            && grant.executionReadinessConstraintHash == plan.executionReadinessConstraintHash
            && grant.executionTimeConstraint == plan.executionTimeConstraint
            && grant.executionTimeConstraintEvidenceHash == plan.executionTimeConstraintEvidenceHash
            && grant.sourceRepositoryHash == plan.sourceRepositoryHash && grant.sourceLaunchId == plan.sourceLaunchId
            && grant.componentGraphHash == plan.componentGraphHash
            && grant.exactRuntimeSetHash == plan.exactRuntimeSetHash
            && grant.componentConfigurationSetHash == plan.componentConfigurationSetHash
            && grant.revenueBindingHash == plan.revenueBindingHash && grant.resultHash == plan.resultHash
            && grant.policyHash == plan.policyHash && grant.securityControlHeadHash == control.securityControlHeadHash
            && grant.securityEpoch == control.securityEpoch && grant.securityEpochHash == control.securityEpochHash
            && grant.policyEpoch == control.policyEpoch && grant.policyEpochHash == control.policyEpochHash
            && grant.reviewControl.reviewGeneration == control.reviewControl.reviewGeneration
            && grant.reviewControl.reviewGenerationHash == control.reviewControl.reviewGenerationHash
            && grant.reviewControl.reviewGeneration == capability.reviewControl.reviewGeneration
            && grant.reviewControl.reviewGenerationHash == capability.reviewControl.reviewGenerationHash;
    }

    function validateCompletedGraphV1(
        address registry,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionProfileCapabilityV1 calldata capability,
        IProgrammableCompletedGraphAdoptionCompatV1.CompletedGraphPlanV1 calldata plan,
        bytes32 sourceCommitHash,
        bytes32 sourceTreeHash,
        IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1[] calldata components,
        IProgrammableCompletedGraphAdoptionCompatV1.GraphEdgeV1[] calldata edges,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionRequestV1 calldata request
    ) external view {
        if (registry == address(0)) revert InvalidBinding(2);
        _requireCodec();
        if (!CODEC.sourceRevisionMatches(plan.sourceCommitId, plan.sourceTreeId, sourceCommitHash, sourceTreeHash)) {
            revert InvalidBinding(2);
        }
        _validatePlanIdentitiesAndPool(capability, plan);
        _validateComponents(registry, capability, plan, components, edges, request);
    }

    function _validatePlanIdentitiesAndPool(
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionProfileCapabilityV1 calldata capability,
        IProgrammableCompletedGraphAdoptionCompatV1.CompletedGraphPlanV1 calldata plan
    ) private view {
        _validateIdentityBit(IDENTITY_TOKEN, plan.identityMask, plan.identities.token != address(0));
        _validateIdentityBit(IDENTITY_HOOK, plan.identityMask, plan.identities.hook != address(0));
        _validateIdentityBit(IDENTITY_NFT, plan.identityMask, plan.identities.nft != address(0));
        _validateIdentityBit(IDENTITY_APPLICATION, plan.identityMask, plan.identities.applicationHash != bytes32(0));
        if (plan.identityMask & ~IDENTITY_MASK_ALL != 0) revert InvalidBinding(3);

        bool hasPool = (plan.identityMask & IDENTITY_POOL) != 0;
        bool completePoolBinding = plan.poolManager != address(0) && plan.poolManagerRuntimeCodeHash != bytes32(0)
            && plan.poolId != bytes32(0) && plan.poolKeyHash != bytes32(0) && plan.poolResultHash != bytes32(0);
        if (hasPool != completePoolBinding) revert InvalidBinding(3);
        if (
            !hasPool
                && (plan.poolManager != address(0)
                    || plan.poolManagerRuntimeCodeHash != bytes32(0)
                    || plan.poolManagerComponentIndex != 0
                    || plan.poolId != bytes32(0)
                    || plan.poolKeyHash != bytes32(0)
                    || plan.poolResultHash != bytes32(0))
        ) revert InvalidBinding(3);
        bool canonicalPoolConfigured = capability.canonicalPoolManagerChainId != 0
            || capability.canonicalPoolManager != address(0)
            || capability.canonicalPoolManagerRuntimeCodeHash != bytes32(0);
        if (canonicalPoolConfigured) {
            if (
                capability.canonicalPoolManagerChainId != block.chainid || capability.canonicalPoolManager == address(0)
                    || capability.canonicalPoolManagerRuntimeCodeHash == bytes32(0)
            ) revert InvalidBinding(3);
        }
        if (
            hasPool
                && (!canonicalPoolConfigured
                    || plan.poolManager != capability.canonicalPoolManager
                    || plan.poolManagerRuntimeCodeHash != capability.canonicalPoolManagerRuntimeCodeHash)
        ) revert InvalidBinding(3);
    }

    function _validateComponents(
        address registry,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionProfileCapabilityV1 calldata capability,
        IProgrammableCompletedGraphAdoptionCompatV1.CompletedGraphPlanV1 calldata plan,
        IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1[] calldata components,
        IProgrammableCompletedGraphAdoptionCompatV1.GraphEdgeV1[] calldata edges,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionRequestV1 calldata request
    ) private view {
        if (components.length == 0 || components.length > MAX_COMPONENTS || edges.length > MAX_EDGES) {
            revert InvalidBinding(4);
        }
        if ((components.length == 1) != (edges.length == 0)) revert InvalidBinding(4);

        RoleScanV1 memory roles;
        roles.tokenFound = (plan.identityMask & IDENTITY_TOKEN) == 0;
        roles.hookFound = (plan.identityMask & IDENTITY_HOOK) == 0;
        roles.nftFound = (plan.identityMask & IDENTITY_NFT) == 0;
        roles.applicationFound = (plan.identityMask & IDENTITY_APPLICATION) == 0;

        address previous;
        for (uint256 i; i < components.length; ++i) {
            IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1 calldata component = components[i];
            _validateComponent(registry, plan, component, i, previous);
            _captureRole(plan, component, roles);
            previous = component.account;
        }
        if (!roles.tokenFound || !roles.hookFound || !roles.nftFound || !roles.applicationFound) {
            revert InvalidBinding(5);
        }
        _validatePoolManagerComponent(plan, components);
        _validateEdges(components, edges);
        if (CODEC.computeComponentGraphHash(components, edges) != plan.componentGraphHash) revert InvalidBinding(5);
        if (CODEC.computeExactRuntimeSetHash(components) != plan.exactRuntimeSetHash) revert InvalidBinding(5);
        if (CODEC.computeComponentConfigurationSetHash(components) != plan.componentConfigurationSetHash) {
            revert InvalidBinding(5);
        }
        _validatePlanCommitments(plan);
        _validateCurrentState(registry, capability, plan, components, edges, request);
    }

    function _validatePlanCommitments(IProgrammableCompletedGraphAdoptionCompatV1.CompletedGraphPlanV1 calldata plan)
        private
        view
    {
        bytes32 configurationHash = CODEC.computeConfigurationHash(
            plan.componentGraphHash,
            plan.componentConfigurationSetHash,
            plan.policyHash,
            plan.revenueBindingHash,
            plan.poolManager,
            plan.poolManagerRuntimeCodeHash,
            plan.poolKeyHash,
            plan.architectureResultHash
        );
        if (configurationHash != plan.configurationHash) revert InvalidBinding(5);
        if (
            CODEC.computeResultHash(
                    plan.componentGraphHash,
                    configurationHash,
                    plan.architectureResultHash,
                    plan.poolResultHash,
                    plan.deploymentLineageHash
                ) != plan.resultHash
        ) revert InvalidBinding(5);
    }

    function _validatePoolManagerComponent(
        IProgrammableCompletedGraphAdoptionCompatV1.CompletedGraphPlanV1 calldata plan,
        IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1[] calldata components
    ) private view {
        if ((plan.identityMask & IDENTITY_POOL) == 0) return;
        if (
            plan.poolManager.code.length == 0 || plan.poolManager.codehash != plan.poolManagerRuntimeCodeHash
                || plan.poolManagerComponentIndex >= components.length
        ) revert InvalidBinding(6);
        IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1 calldata component =
            components[plan.poolManagerComponentIndex];
        if (
            component.account != plan.poolManager || component.runtimeCodeHash != plan.poolManagerRuntimeCodeHash
                || component.deploymentKind
                    != IProgrammableCompletedGraphAdoptionCompatV1.DeploymentKindV1.ExternalCanonical
        ) revert InvalidBinding(6);
    }

    function _validateComponent(
        address registry,
        IProgrammableCompletedGraphAdoptionCompatV1.CompletedGraphPlanV1 calldata plan,
        IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1 calldata component,
        uint256 index,
        address previous
    ) private view {
        if (
            component.account == address(0) || component.account <= previous || component.account.code.length == 0
                || component.kind == IProgrammableCompletedGraphAdoptionCompatV1.ComponentKindV1.Invalid
                || component.scope == IProgrammableCompletedGraphAdoptionCompatV1.ComponentScopeV1.Invalid
                || component.deploymentKind == IProgrammableCompletedGraphAdoptionCompatV1.DeploymentKindV1.Invalid
                || component.runtimeCodeHash == bytes32(0) || component.configurationHash == bytes32(0)
                || component.creationEvidenceHash == bytes32(0)
                || component.account.codehash != component.runtimeCodeHash
                || CODEC.computeComponentConfigurationHash(component) != component.configurationHash
                || CODEC.computeComponentCreationEvidenceHash(registry, plan, index, component)
                    != component.creationEvidenceHash
        ) revert InvalidBinding(7);

        if (component.deploymentKind == IProgrammableCompletedGraphAdoptionCompatV1.DeploymentKindV1.Create) {
            if (
                component.deployer == address(0) || component.create2Salt != bytes32(0)
                    || component.initCodeHash == bytes32(0) || component.externalCanonicalIdHash != bytes32(0)
                    || _computeCreateAddress(component.deployer, component.createNonce) != component.account
            ) revert InvalidBinding(7);
            _validateCreationReceiptEvidence(component);
        } else if (component.deploymentKind == IProgrammableCompletedGraphAdoptionCompatV1.DeploymentKindV1.Create2) {
            if (
                component.deployer == address(0) || component.createNonce != 0 || component.initCodeHash == bytes32(0)
                    || component.externalCanonicalIdHash != bytes32(0)
                    || _computeCreate2Address(component.create2Salt, component.initCodeHash, component.deployer)
                        != component.account
            ) revert InvalidBinding(7);
            _validateCreationReceiptEvidence(component);
        } else if (
            component.deploymentKind == IProgrammableCompletedGraphAdoptionCompatV1.DeploymentKindV1.ExternalCanonical
        ) {
            if (
                component.deployer != address(0) || component.createNonce != 0 || component.create2Salt != bytes32(0)
                    || component.initCodeHash != bytes32(0) || component.externalCanonicalIdHash == bytes32(0)
                    || !_emptyCreationReceiptEvidence(component.creationReceiptEvidence)
            ) revert InvalidBinding(7);
        } else {
            revert InvalidBinding(7);
        }
    }

    function _captureRole(
        IProgrammableCompletedGraphAdoptionCompatV1.CompletedGraphPlanV1 calldata plan,
        IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1 calldata component,
        RoleScanV1 memory roles
    ) private view {
        if (
            component.kind == IProgrammableCompletedGraphAdoptionCompatV1.ComponentKindV1.Token
                && component.account == plan.identities.token
        ) {
            if (roles.tokenFound) revert InvalidBinding(8);
            roles.tokenFound = true;
        } else if (
            component.kind == IProgrammableCompletedGraphAdoptionCompatV1.ComponentKindV1.Hook
                && component.account == plan.identities.hook
        ) {
            if (roles.hookFound) revert InvalidBinding(8);
            roles.hookFound = true;
        } else if (
            component.kind == IProgrammableCompletedGraphAdoptionCompatV1.ComponentKindV1.Nft
                && component.account == plan.identities.nft
        ) {
            if (roles.nftFound) revert InvalidBinding(8);
            roles.nftFound = true;
        } else if (
            component.kind == IProgrammableCompletedGraphAdoptionCompatV1.ComponentKindV1.Application
                && CODEC.computeApplicationIdentityHash(component) == plan.identities.applicationHash
        ) {
            if (roles.applicationFound) revert InvalidBinding(8);
            roles.applicationFound = true;
        }
    }

    function _validateEdges(
        IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1[] calldata components,
        IProgrammableCompletedGraphAdoptionCompatV1.GraphEdgeV1[] calldata edges
    ) private pure {
        uint256 reachable = 1;
        for (uint256 i; i < edges.length; ++i) {
            IProgrammableCompletedGraphAdoptionCompatV1.GraphEdgeV1 calldata edge = edges[i];
            if (
                edge.fromIndex >= components.length || edge.toIndex >= components.length
                    || edge.fromIndex == edge.toIndex
                    || edge.kind == IProgrammableCompletedGraphAdoptionCompatV1.EdgeKindV1.Invalid
                    || edge.relationHash == bytes32(0) || (i != 0 && !_edgeLess(edges[i - 1], edge))
            ) revert InvalidBinding(9);
        }
        for (uint256 pass; pass < components.length; ++pass) {
            uint256 before = reachable;
            for (uint256 i; i < edges.length; ++i) {
                IProgrammableCompletedGraphAdoptionCompatV1.GraphEdgeV1 calldata edge = edges[i];
                if ((reachable & (uint256(1) << edge.fromIndex)) != 0) reachable |= uint256(1) << edge.toIndex;
            }
            if (reachable == before) break;
        }
        if (reachable != (uint256(1) << components.length) - 1) revert InvalidBinding(9);
    }

    function _edgeLess(
        IProgrammableCompletedGraphAdoptionCompatV1.GraphEdgeV1 calldata left,
        IProgrammableCompletedGraphAdoptionCompatV1.GraphEdgeV1 calldata right
    ) private pure returns (bool) {
        if (left.fromIndex != right.fromIndex) return left.fromIndex < right.fromIndex;
        if (left.toIndex != right.toIndex) return left.toIndex < right.toIndex;
        if (left.kind != right.kind) return uint8(left.kind) < uint8(right.kind);
        return uint256(left.relationHash) < uint256(right.relationHash);
    }

    function _validateIdentityBit(uint16 bit, uint16 mask, bool present) private pure {
        if (((mask & bit) != 0) != present) revert InvalidBinding(10);
    }

    function _validateCurrentState(
        address registry,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionProfileCapabilityV1 calldata capability,
        IProgrammableCompletedGraphAdoptionCompatV1.CompletedGraphPlanV1 calldata plan,
        IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1[] calldata components,
        IProgrammableCompletedGraphAdoptionCompatV1.GraphEdgeV1[] calldata edges,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionRequestV1 calldata request
    ) private view {
        (bytes32 architectureStateHash, bytes32 poolStateHash, bytes32 revenueStateHash) =
            _readCurrentState(registry, capability, plan, components, edges, request);
        _validateCurrentStateHashes(plan, request, architectureStateHash, poolStateHash, revenueStateHash);
    }

    function _readCurrentState(
        address registry,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionProfileCapabilityV1 calldata capability,
        IProgrammableCompletedGraphAdoptionCompatV1.CompletedGraphPlanV1 calldata plan,
        IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1[] calldata components,
        IProgrammableCompletedGraphAdoptionCompatV1.GraphEdgeV1[] calldata edges,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionRequestV1 calldata request
    ) private view returns (bytes32 architectureStateHash, bytes32 poolStateHash, bytes32 revenueStateHash) {
        address verifier = capability.stateVerifierBinding.stateVerifier;
        if (
            verifier.code.length == 0 || capability.stateVerifierBinding.stateVerifierRuntimeCodeHash == bytes32(0)
                || verifier.codehash != capability.stateVerifierBinding.stateVerifierRuntimeCodeHash
                || capability.stateVerifierBinding.stateSchemaHash == bytes32(0)
                || capability.stateVerifierBinding.stateVerifierBehaviorEvidenceHash == bytes32(0)
                || _containsDelegateCallOpcode(verifier)
        ) revert InvalidBinding(12);
        bytes memory data = abi.encodeCall(
            IProgrammableCompletedGraphAdoptionStateVerifierV1.verifyCurrentStateV1,
            (registry, capability, plan, components, edges, request)
        );
        bytes memory result = new bytes(96);
        bool success;
        uint256 returnDataSize;
        uint256 callGas = gasleft();
        if (callGas <= STATE_VERIFIER_GAS_RESERVE) revert InvalidBinding(12);
        unchecked {
            callGas -= STATE_VERIFIER_GAS_RESERVE;
        }
        if (callGas > MAX_STATE_VERIFIER_STATICCALL_GAS) callGas = MAX_STATE_VERIFIER_STATICCALL_GAS;
        assembly ("memory-safe") {
            success := staticcall(callGas, verifier, add(data, 0x20), mload(data), add(result, 0x20), 96)
            returnDataSize := returndatasize()
        }
        if (!success || returnDataSize != 96) revert InvalidBinding(12);
        return abi.decode(result, (bytes32, bytes32, bytes32));
    }

    function _validateCurrentStateHashes(
        IProgrammableCompletedGraphAdoptionCompatV1.CompletedGraphPlanV1 calldata plan,
        IProgrammableCompletedGraphAdoptionCompatV1.AdoptionRequestV1 calldata request,
        bytes32 architectureStateHash,
        bytes32 poolStateHash,
        bytes32 revenueStateHash
    ) private pure {
        if (
            architectureStateHash != request.currentArchitectureStateHash
                || poolStateHash != request.currentPoolStateHash || revenueStateHash != request.currentRevenueStateHash
                || (plan.revenueBindingHash == bytes32(0)) != (revenueStateHash == bytes32(0))
        ) revert InvalidBinding(12);
    }

    function _validateCreationReceiptEvidence(
        IProgrammableCompletedGraphAdoptionCompatV1.ComponentV1 calldata component
    ) private pure {
        IProgrammableCompletedGraphAdoptionCompatV1.CreationReceiptEvidenceV1 calldata
            evidence = component.creationReceiptEvidence;
        if (
            evidence.transactionHash == bytes32(0) || evidence.blockNumber == 0 || evidence.blockHash == bytes32(0)
                || evidence.transactionSender == address(0) || evidence.transactionInputHash == bytes32(0)
                || !evidence.receiptSucceeded || evidence.finalityEvidenceHash == bytes32(0)
                || evidence.dualProviderEvidenceHash == bytes32(0)
        ) revert InvalidBinding(13);
        if (component.deploymentKind == IProgrammableCompletedGraphAdoptionCompatV1.DeploymentKindV1.Create) {
            if (
                evidence.transactionSender != component.deployer
                    || evidence.transactionSenderNonce != component.createNonce || evidence.transactionTo != address(0)
                    || evidence.transactionInputHash != component.initCodeHash
                    || evidence.topLevelCreatedAddress != component.account
                    || evidence.internalCreationTraceHash != bytes32(0)
            ) revert InvalidBinding(13);
        } else if (component.deploymentKind == IProgrammableCompletedGraphAdoptionCompatV1.DeploymentKindV1.Create2) {
            bool outerCreate = evidence.transactionTo == address(0);
            address expectedTopLevelCreatedAddress = outerCreate
                ? _computeCreateAddress(evidence.transactionSender, evidence.transactionSenderNonce)
                : address(0);
            if (
                evidence.topLevelCreatedAddress != expectedTopLevelCreatedAddress
                    || evidence.internalCreationTraceHash == bytes32(0)
            ) {
                revert InvalidBinding(13);
            }
        } else {
            revert InvalidBinding(13);
        }
    }

    function _emptyCreationReceiptEvidence(
        IProgrammableCompletedGraphAdoptionCompatV1.CreationReceiptEvidenceV1 calldata evidence
    ) private pure returns (bool) {
        return evidence.transactionHash == bytes32(0) && evidence.blockNumber == 0 && evidence.blockHash == bytes32(0)
            && evidence.transactionIndex == 0 && evidence.transactionSender == address(0)
            && evidence.transactionSenderNonce == 0 && evidence.transactionTo == address(0)
            && evidence.transactionValueWei == 0 && evidence.transactionInputHash == bytes32(0)
            && !evidence.receiptSucceeded && evidence.topLevelCreatedAddress == address(0)
            && evidence.internalCreationTraceHash == bytes32(0) && evidence.finalityEvidenceHash == bytes32(0)
            && evidence.dualProviderEvidenceHash == bytes32(0);
    }

    function _containsDelegateCallOpcode(address dependency) private view returns (bool) {
        bytes memory runtime = dependency.code;
        for (uint256 i; i < runtime.length; ++i) {
            uint8 opcode = uint8(runtime[i]);
            if (opcode == 0xf4) return true;
            if (opcode >= 0x60 && opcode <= 0x7f) {
                unchecked {
                    i += opcode - 0x5f;
                }
            }
        }
        return false;
    }

    function _computeCreate2Address(bytes32 salt, bytes32 initCodeHash, address deployer)
        private
        pure
        returns (address)
    {
        return address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), deployer, salt, initCodeHash)))));
    }

    function _computeCreateAddress(address deployer, uint64 nonce) private pure returns (address) {
        if (nonce == 0) {
            return address(uint160(uint256(keccak256(abi.encodePacked(hex"d694", deployer, hex"80")))));
        }
        if (nonce <= 0x7f) {
            // `nonce <= 0x7f` above proves this one-byte RLP value cannot truncate.
            // forge-lint: disable-next-line(unsafe-typecast)
            return address(uint160(uint256(keccak256(abi.encodePacked(hex"d694", deployer, bytes1(uint8(nonce)))))));
        }
        uint256 nonceBytes;
        uint64 remaining = nonce;
        while (remaining != 0) {
            ++nonceBytes;
            remaining >>= 8;
        }
        bytes memory encodedNonce = new bytes(nonceBytes);
        remaining = nonce;
        for (uint256 i = nonceBytes; i != 0; --i) {
            // RLP serializes the low-order octet on each iteration, then shifts it away.
            // forge-lint: disable-next-line(unsafe-typecast)
            encodedNonce[i - 1] = bytes1(uint8(remaining));
            remaining >>= 8;
        }
        return address(
            uint160(
                uint256(
                    keccak256(
                        abi.encodePacked(
                            // A uint64 nonce uses at most eight bytes, so this prefix is at most 0xe6.
                            // forge-lint: disable-next-line(unsafe-typecast)
                            bytes1(uint8(0xc0 + 22 + nonceBytes)),
                            bytes1(0x94),
                            deployer,
                            // `nonceBytes` is in [1, 8], so this prefix is at most 0x88.
                            // forge-lint: disable-next-line(unsafe-typecast)
                            bytes1(uint8(0x80 + nonceBytes)),
                            encodedNonce
                        )
                    )
                )
            )
        );
    }

    function _requireCodec() private view {
        if (address(CODEC).codehash != CODEC_RUNTIME_CODE_HASH) revert InvalidBinding(11);
    }
}

